B.aRY=s(["\u0634\u0647\u062f \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0643\u0644 \u0627\u0644\u063a\u0632\u0648\u0627\u062a \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0643\u0627\u0646 \u0641\u064a \u0643\u0644 \u0645\u0648\u0642\u0639\u0629 \u0641\u0627\u0631\u0633\u064b\u0627 \u062b\u0627\u0628\u062a\u064b\u0627 \u0644\u0627 \u064a\u062a\u0632\u062d\u0632\u062d\u060c \u0648\u0641\u064a \u0628\u062f\u0631 \u064a\u0648\u0645 \u0627\u0644\u0641\u0631\u0642\u0627\u0646\u060c \u062a\u0648\u062c\u0651\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0642\u0650\u0628\u0644\u0629\u060c \u0648\u0631\u0641\u0639 \u064a\u062f\u064a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0648\u0642\u0627\u0644: \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645 \u0623\u0646\u062c\u0650\u0632 \u0645\u0627 \u0648\u0639\u064e\u062f\u062a\u0646\u0650\u064a\u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645 \u0622\u062a\u0650 \u0645\u0627 \u0648\u0639\u064e\u062f\u062a\u0646\u0650\u064a\u060c \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645 \u0625\u0650\u0646 \u062a\u064f\u0647\u0644\u0650\u0643 \u0647\u0630\u0650\u0647\u0650 \u0627\u0644\u0639\u0635\u064e\u0627\u0628\u0629 \u0645\u0650\u0646 \u0623\u0647\u0644\u0650 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u0650\u060c \u0644\u0627 \u062a\u064f\u0639\u0628\u064e\u062f \u0641\u0650\u064a \u0627\u0644\u0623\u0631\u0636\u0650.","\u0648\u0643\u0627\u0646 \ufdfa \u064a\u064f\u0643\u062b\u0650\u0631 \u0645\u0646 \u0627\u0644\u062f\u0639\u0627\u0621 \u062d\u062a\u0649 \u0633\u0642\u0637 \u0631\u0650\u062f\u0627\u0624\u0647 \u0639\u0646 \u0645\u064e\u0646\u0643\u0628\u064a\u0647\u060c \u0641\u062c\u0627\u0621\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d\u060c \u0641\u0631\u062f\u0651\u064e \u0639\u0644\u064a\u0647 \u0631\u062f\u0627\u0621\u0647 \u0648\u0642\u0627\u0644: \u064a\u0627 \u0646\u0628\u064a \u0627\u0644\u0644\u0647\u060c \u0643\u0641\u0627\u0643 \u0645\u0646\u0627\u0634\u062f\u062a\u0643 \u0631\u0628\u0643\u060c \u0641\u0625\u0646\u0647 \u0645\u0646\u062c\u0650\u0632\u064c \u0644\u0643 \u0645\u0627 \u0648\u0639\u062f\u0643\u060c \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0625\u0650\u0630\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u063a\u0650\u064a\u062b\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064e \u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0651\u0650\u064a \u0645\u064f\u0645\u0650\u062f\u0651\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0623\u064e\u0644\u0652\u0641\u064d \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u0650 \u0645\u064f\u0631\u0652\u062f\u0650\u0641\u0650\u064a\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0646\u0641\u0627\u0644","\u062b\u0645 \u062b\u0628\u062a \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u064a\u0648\u0645 \u0623\u062d\u062f\u060c \u062d\u064a\u0646 \u0627\u0647\u062a\u0632\u0651\u062a \u0627\u0644\u0635\u0641\u0648\u0641 \u0645\u0639 \u0642\u0644\u0651\u0629 \u0645\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629: \u0623\u0628\u0648 \u0639\u0628\u064a\u062f\u0629 \u0648\u0639\u0644\u0649 \u0648\u0637\u0644\u062d\u0629 \u0648\u0627\u0644\u0632\u0628\u064a\u0631 \u0648\u0639\u0645\u0631\u060c \u064a\u062f\u0627\u0641\u0639\u0648\u0646 \u0639\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0623\u062c\u0633\u0627\u062f\u0647\u0645 \u0648\u0633\u064a\u0648\u0641\u0647\u0645\u060c \u0641\u0644\u0645 \u064a\u0641\u0631\u0651 \u0648\u0644\u0645 \u064a\u062a\u0631\u0627\u062c\u0639.","\u0648\u0641\u064a \u0627\u0644\u0623\u062d\u0632\u0627\u0628\u060c \u062d\u064a\u062b \u0627\u0644\u062c\u0648\u0639 \u0648\u0627\u0644\u062e\u0648\u0641 \u0648\u0627\u0644\u0631\u064a\u062d\u060c \u0643\u0627\u0646 \u064a\u064f\u0634\u0627\u0631\u0643 \u0641\u064a \u0627\u0644\u062d\u0641\u0631\u060c \u064a\u064f\u063a\u0627\u0644\u0628 \u0627\u0644\u062a\u0639\u0628\u060c \u0648\u064a\u0634\u062f\u0651 \u0645\u0646 \u0623\u0632\u0631 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646\u060c \u0648\u0643\u0627\u0646 \u0635\u0648\u062a\u0647 \u0641\u064a \u0627\u0644\u062f\u0639\u0627\u0621 \u0645\u0639 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0627\u0644\u0635\u062d\u0627\u0628\u0629\u060c \u064a\u064f\u0642\u0627\u0648\u0645\u0648\u0646 \u0627\u0644\u062d\u0635\u0627\u0631 \u0628\u0627\u0644\u062f\u0639\u0627\u0621 \u0648\u0627\u0644\u0639\u0645\u0644\u060c \u0648\u064a\u0648\u0642\u0646\u0648\u0646 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0646\u0627\u0635\u0631\u064f \u062c\u064f\u0646\u062f\u0647."],t.s)
