B.aOL=s(["\u0635\u0639\u062f\u062a \u0631\u0648\u062d\u064f \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0631\u0641\u064a\u0642 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0644\u0645 \u064a\u064f\u0648\u0627\u0631\u064e \u062c\u0633\u062f\u0647 \u0627\u0644\u0637\u0627\u0647\u0631 \u0627\u0644\u062b\u0631\u0649 \u0628\u0639\u062f\u060c \u0648\u0627\u0644\u0645\u0648\u0642\u0641 \u0645\u0647\u064a\u0628\u060c \u0641\u0644\u0645 \u064a\u0639\u062f \u0647\u0646\u0627\u0643 \u0648\u062d\u064a\u064c \u064a\u064f\u0646\u0632\u0644\u060c \u0648\u0627\u0644\u0623\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0641\u062a\u0631\u0642\u060c \u062a\u0646\u062a\u0638\u0631 \u0645\u0646 \u064a\u062e\u0644\u0641 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0648\u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u0622\u0646 \u0628\u064a\u0646 \u0627\u0644\u0627\u062c\u062a\u0647\u0627\u062f \u0648\u0627\u0644\u0631\u0623\u064a \u0648\u0627\u0644\u0634\u0648\u0631\u0649.","\u0644\u0642\u062f \u0622\u0646 \u0644\u0644\u0635\u062d\u0627\u0628\u0629 \u0623\u0646 \u064a\u062e\u062a\u0627\u0631\u0648\u0627 \u0648\u064a\u062a\u062d\u0645\u0651\u0644\u0648\u0627 \u0627\u0644\u0639\u0628\u0621\u060c \u0644\u064a\u064f\u062b\u0628\u062a\u0648\u0627 \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062a\u0631\u0643 \u062e\u0644\u0641\u0647 \u0631\u062c\u0627\u0644\u064b\u0627 \u0642\u0627\u062f\u0631\u064a\u0646 \u0639\u0644\u0649 \u062d\u0645\u0644 \u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0628\u0635\u062f\u0642\u064d \u0648\u062b\u0628\u0627\u062a\u060c \u0644\u0627 \u062a\u0632\u0644\u0651 \u0623\u0642\u062f\u0627\u0645\u0647\u0645 \u0625\u0630\u0627 \u0639\u0635\u0641\u062a \u0627\u0644\u0641\u062a\u0646\u0629\u060c \u0648\u0644\u0627 \u062a\u0644\u064a\u0646 \u0639\u0632\u0627\u0626\u0645\u0647\u0645 \u062d\u064a\u0646 \u062a\u0634\u062a\u062f\u0651 \u0627\u0644\u0645\u062d\u0646."],t.s)
