B.awB=s(["\u0623\u0631\u0627\u062f \u0639\u0645\u0631 \u0623\u0646 \u064a\u062a\u0643\u0644\u0645\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d: \u062a\u0645\u0647\u0651\u0644\u060c \u0648\u0643\u0627\u0646 \u0639\u0645\u0631 \u064a\u0642\u0648\u0644: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0623\u0631\u062f\u062a \u0628\u0630\u0644\u0643 \u0625\u0644\u0627 \u0623\u0646\u064a \u0642\u062f \u0647\u064a\u0651\u0623\u062a \u0643\u0644\u0627\u0645\u064b\u0627 \u0642\u062f \u0623\u0639\u062c\u0628\u0646\u064a\u060c \u062e\u0634\u064a\u062a \u0623\u0644\u0627 \u064a\u0628\u0644\u063a\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d\u060c \u062b\u0645 \u062a\u0643\u0644\u0645 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0641\u0643\u0627\u0646 \u0623\u062d\u0644\u064e\u0645 \u0645\u0650\u0646\u0651\u0650\u064a \u0648\u0623\u0648\u0642\u0631\u064e.","\u0648\u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0623\u0646 \u0639\u0645\u0631 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0643\u0627\u0646 \u064a\u062e\u0634\u0649 \u0623\u0646 \u064a\u0633\u0628\u0642 \u0623\u0628\u0627 \u0628\u0643\u0631\u064d \u0628\u0627\u0644\u0643\u0644\u0627\u0645\u060c \u0641\u064a\u062e\u062a\u0644\u0641 \u0642\u0648\u0644\u0647 \u0639\u0646 \u0642\u0648\u0644 \u0623\u0628\u064a \u0628\u0643\u0631\u064d\u060c \u0625\u0630 \u0644\u0645 \u064a\u0643\u0646 \u0628\u064a\u0646\u0647\u0645\u0627 \u062a\u0634\u0627\u0648\u0631\u064c \u0645\u064f\u0633\u0628\u0642\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0645\u0642\u0627\u0645 \u064a\u0642\u062a\u0636\u064a \u0643\u0644\u0645\u0629\u064b \u0645\u0648\u062d\u0651\u062f\u0629 \u062a\u064f\u062c\u0645\u0650\u0639 \u0627\u0644\u0642\u0644\u0648\u0628 \u0648\u0644\u0627 \u062a\u064f\u0641\u0631\u0651\u0642\u0647\u0627.","\u062b\u0645 \u0648\u0642\u0641 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0623\u0645\u0627\u0645 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u064a\u062a\u062d\u062f\u062b \u0628\u062d\u0643\u0645\u0629\u060c \u0645\u0628\u062a\u062f\u0626\u064b\u0627 \u0643\u0644\u0627\u0645\u0647 \u0628\u0625\u0642\u0631\u0627\u0631 \u0641\u0636\u0644\u0647\u0645 \u0648\u0645\u0643\u0627\u0646\u062a\u0647\u0645\u060c \u0641\u0642\u0627\u0644: \u0645\u0627 \u0630\u0643\u0631\u062a\u064f\u0645 \u0641\u064a\u0643\u0645 \u0645\u0646 \u062e\u064a\u0631\u064d \u0641\u0623\u0646\u062a\u0645 \u0644\u0647 \u0623\u0647\u0644\u064c\u060c \u0648\u0644\u0646 \u064a\u064f\u0639\u0631\u0641 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0625\u0644\u0627 \u0644\u0647\u0630\u0627 \u0627\u0644\u062d\u064a\u0651 \u0645\u0646 \u0642\u0631\u064a\u0634\u060c \u0647\u0645 \u0623\u0648\u0633\u0637 \u0627\u0644\u0639\u0631\u0628 \u0646\u0633\u0628\u064b\u0627 \u0648\u062f\u0627\u0631\u064b\u0627.","\u0642\u062f \u0627\u0633\u062a\u062f\u0644\u0651\u064e \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0639\u0644\u0649 \u0630\u0644\u0643 \u0628\u062d\u062f\u064a\u062b \u0627\u0644\u0646\u0628\u064a \ufdfa: \u0644\u0627 \u064a\u0632\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0641\u064a \u0642\u0631\u064a\u0634 \u0645\u0627 \u0628\u0642\u064a \u0645\u0646\u0647\u0645 \u0627\u062b\u0646\u0627\u0646 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a\u060c \u0648\u0647\u0648 \u0646\u0635\u0651\u064c \u0635\u0631\u064a\u062d\u064c \u0641\u064a \u0623\u0646 \u0627\u0644\u062e\u0644\u0627\u0641\u0629 \u0644\u0627 \u062a\u0643\u0648\u0646 \u0625\u0644\u0627 \u0641\u064a \u0642\u0631\u064a\u0634.","\u062b\u0645 \u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d: \u0648\u0625\u0646\u0651\u0650\u064a \u0642\u062f \u0631\u0636\u064a\u062a\u064f \u0644\u0643\u0645 \u0623\u062d\u062f \u0647\u0630\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646\u060c \u0641\u0628\u0627\u064a\u0639\u0648\u0627 \u0623\u064a\u0647\u0645\u0627 \u0634\u0626\u062a\u0645\u060c \u0645\u0634\u064a\u0631\u064b\u0627 \u0625\u0644\u0649 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0648\u0623\u0628\u064a \u0639\u0628\u064a\u062f\u0629 \u0628\u0646 \u0627\u0644\u062c\u0631\u0627\u062d\u060c \u0648\u0643\u0627\u0646 \u0641\u064a \u0625\u0634\u0627\u0631\u062a\u0647 \u062a\u0631\u0641\u0651\u0639\u064c \u0639\u0646 \u0637\u0644\u0628 \u0627\u0644\u0625\u0645\u0627\u0631\u0629\u060c \u0648\u062a\u0623\u0643\u064a\u062f \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u064a\u062c\u0628 \u0623\u0646 \u064a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0627\u0644\u0634\u0648\u0631\u0649."],t.s)
