B.azC=s(["\u0627\u0634\u062a\u062f\u0651 \u0639\u0644\u0649 \u0627\u0644\u0635\u062f\u064a\u0642 \u0627\u0644\u0645\u0631\u0636\u060c \u0648\u0628\u062f\u0623\u062a \u0623\u0646\u0641\u0627\u0633\u0647 \u062a\u062a\u0642\u0637\u0651\u0639\u060c \u0648\u0644\u0645 \u064a\u0643\u0646 \u064a\u0634\u0643\u0648 \u0645\u0646 \u0645\u0631\u0636\u0647\u060c \u0628\u0644 \u0631\u0627\u0636\u064a\u064b\u0627 \u0628\u0647\u060c \u0648\u0643\u0627\u0646 \u064a\u0631\u062f\u0651\u062f \u0641\u064a \u062e\u0634\u0648\u0639\u064d \u0648\u0631\u0636\u0627: \u0627\u0644\u0644\u0647\u0645 \u062a\u0648\u0641\u0651\u0646\u064a \u0645\u0633\u0644\u0645\u064b\u0627 \u0648\u0623\u0644\u062d\u0642\u0646\u064a \u0628\u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646.","\u0648\u0641\u064a \u0627\u0644\u0644\u064a\u0644\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629\u060c \u0623\u0633\u0644\u0645 \u0627\u0644\u0631\u0648\u062d\u060c \u0631\u0627\u0636\u064a\u064b\u0627 \u0645\u0637\u0645\u0626\u0646\u064b\u0627\u060c \u062a\u064f\u0648\u0641\u064a \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u064a \u062c\u0645\u0627\u062f\u0649 \u0627\u0644\u0622\u062e\u0631\u0629 \u0633\u0646\u0629 13 \u0647\u0640\u060c \u0639\u0646 \u062b\u0644\u0627\u062b\u0629 \u0648\u0633\u062a\u064a\u0646 \u0639\u0627\u0645\u064b\u0627\u060c \u0646\u0641\u0633 \u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0630\u064a \u062a\u064f\u0648\u0641\u064a \u0641\u064a\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0628\u0639\u062f \u062e\u0644\u0627\u0641\u0629\u064d \u062f\u0627\u0645\u062a \u0633\u0646\u062a\u064a\u0646 \u0648\u062b\u0644\u0627\u062b\u0629 \u0623\u0634\u0647\u0631."],t.s)
