B.ap1=new A.h("walidaynHadiths_6","\u0645\u0642\u0627\u0645 \u0627\u0644\u0631\u064e\u0651\u062d\u0645 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u0650 \u0639\u0632\u064e\u0651 \u0648\u062c\u0644\u064e\u0651","\u0639\u064e\u0646 \u0623\u0628\u064a \u0647\u064f\u0631\u064a\u0631\u064e\u0629 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u060c \u0639\u0646 \u0627\u0644\u0646\u0628\u064a\u0651\u0650 \ufdfa \u0642\u0627\u0644\u064e: \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u062e\u064e\u0644\u0642\u064e\u060c \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0641\u064e\u0631\u064e\u063a\u064e \u0645\u0646\u0647 \u0642\u0627\u0645\u064e\u062a\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u0645\u064f\u060c \u0641\u0623\u062e\u064e\u0630\u064e\u062a \u0628\u062d\u064e\u0642\u0648\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0645\u064e\u0646\u0650\u060c \u0641\u0642\u0627\u0644\u064e \u0644\u0647: \u0645\u064e\u0647\u060c \u0642\u0627\u0644\u064e\u062a: \u0647\u0630\u0627 \u0645\u064e\u0642\u0627\u0645\u064f \u0627\u0644\u0639\u0627\u0626\u0650\u0630\u0650 \u0628\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0642\u064e\u0637\u0650\u064a\u0639\u064e\u0629\u0650\u060c \u0642\u0627\u0644\u064e: \u0623\u0644\u0627 \u062a\u064e\u0631\u0636\u064e\u064a\u0646\u064e \u0623\u0646 \u0623\u0635\u0650\u0644\u064e \u0645\u064e\u0646 \u0648\u0635\u064e\u0644\u064e\u0643\u0650\u060c \u0648\u0623\u064e\u0642\u0637\u064e\u0639\u064e \u0645\u064e\u0646 \u0642\u064e\u0637\u064e\u0639\u064e\u0643\u0650\u060c \u0642\u0627\u0644\u064e\u062a: \u0628\u064e\u0644\u064e\u0649 \u064a\u0627 \u0631\u064e\u0628\u0651\u0650\u060c \u0642\u0627\u0644\u064e: \u0641\u064e\u0630\u0627\u0643\u0650. \u0642\u0627\u0644\u064e \u0623\u0628\u0648 \u0647\u064f\u0631\u064e\u064a\u0631\u064e\u0629\u064e: \u0627\u0642\u0631\u064e\u0624\u064f\u0648\u0627 \u0625\u0646 \u0634\u0650\u0626\u062a\u064f\u0645: \ufd3f\u0641\u064e\u0647\u064e\u0644 \u0639\u064e\u0633\u064e\u064a\u062a\u064f\u0645 \u0625\u0650\u0646 \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u064a\u062a\u064f\u0645 \u0623\u064e\u0646 \u062a\u064f\u0641\u0633\u0650\u062f\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0623\u064e\u0631\u0636\u0650 \u0648\u064e\u062a\u064f\u0642\u064e\u0637\u0651\u0650\u0639\u064f\u0648\u0627 \u0623\u064e\u0631\u062d\u064e\u0627\u0645\u064e\u0643\u064f\u0645\ufd3e - \u0633\u0648\u0631\u0629 \u0645\u062d\u0645\u062f . (\u0648\u0641\u064a \u0631\u0648\u0627\u064a\u0629): \u0642\u0627\u0644\u064e \u0631\u064e\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \ufdfa: \u0648\u0627\u0642\u0631\u064e\u0624\u064f\u0648\u0627 \u0625\u0646 \u0634\u0650\u0626\u062a\u064f\u0645: \ufd3f\u0641\u064e\u0647\u064e\u0644 \u0639\u064e\u0633\u064e\u064a\u062a\u064f\u0645\ufd3e. - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aKA)
