B.aD9=s([u.e0,"\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650 \u062f\u064e\u0644\u0651\u064e \u0631\u064e\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0627\u0644\u0645\u0633\u0644\u0650\u0645\u064e \u0639\u0644\u0649 \u0645\u0627 \u062a\u064f\u0648\u0636\u064e\u0639\u064f \u0628\u0647 \u062e\u064e\u0637\u0627\u064a\u0627 \u0627\u0644\u0639\u064e\u0628\u062f\u0650 \u0648\u0630\u064f\u0646\u0648\u0628\u064f\u0647 \u0648\u062a\u064f\u0645\u062d\u064e\u0649\u060c \u0648\u0644\u0648 \u0643\u0627\u0646\u062a \u0643\u064e\u062b\u064a\u0631\u0629\u064b \u0643\u064e\u0632\u064e\u0628\u064e\u062f\u0650 \u0627\u0644\u0628\u064e\u062d\u0631\u0650\u060c \u0648\u0647\u0648: \u0645\u0627 \u064a\u064e\u0639\u0644\u0648 \u0627\u0644\u0628\u064e\u062d\u0631\u064e \u0645\u0650\u0646 \u0627\u0644\u0631\u063a\u0648\u0629\u0650 \u0648\u0627\u0644\u0641\u064e\u0642\u0627\u0642\u064a\u0639\u0650 \u0639\u0646\u062f\u064e \u062a\u0645\u0648\u0651\u064f\u062c\u0650\u0647 \u0648\u0647\u064e\u064a\u064e\u062c\u0627\u0646\u0650\u0647\u060c \u0648\u064a\u064f\u0639\u0628\u0651\u064e\u0631\u064f \u0628\u0647 \u0639\u0646 \u0643\u064e\u062b\u0631\u0629\u0650 \u0627\u0644\u0630\u0651\u064f\u0646\u0648\u0628\u0650 \u0648\u0639\u064e\u062f\u064e\u0645\u0650 \u062d\u064e\u0635\u0631\u0650\u0647\u0627\u060c \u0648\u0645\u0639\u064e \u0643\u064e\u062b\u0631\u062a\u0650\u0647\u0627 \u0627\u0644\u0647\u0627\u0626\u0644\u0629\u0650 \u064a\u064e\u063a\u0641\u0650\u0631\u064f\u0647\u0627 \u0627\u0644\u0644\u0647\u064f \u0644\u0650\u0645\u064e\u0646 \u0623\u062a\u0649 \u0628\u0647\u0630\u0627 \u0627\u0644\u0630\u0651\u0650\u0643\u0631\u0650\u060c \u0648\u062a\u0644\u0643 \u0645\u064f\u0628\u0627\u0644\u064e\u063a\u0629\u064c \u0641\u064a \u0628\u064e\u064a\u0627\u0646\u0650 \u0633\u064e\u0639\u0629\u0650 \u0645\u064e\u063a\u0641\u0631\u0629\u0650 \u0627\u0644\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u064e\u0649 \u0648\u0639\u064e\u0638\u064a\u0645\u0650 \u0631\u064e\u062d\u0645\u062a\u0650\u0647\u061b \u0648\u0630\u0644\u0643 \u0628\u0623\u0646 \u064a\u0642\u0648\u0644\u064e \u0641\u064a \u0627\u0644\u064a\u0648\u0645\u0650 \u0645\u0650\u0627\u0626\u0629\u064e \u0645\u0631\u0651\u064e\u0629\u064d: \xab\u0633\u064f\u0628\u062d\u0627\u0646\u064e \u0627\u0644\u0644\u0647\u0650 \u0648\u0628\u0650\u062d\u064e\u0645\u062f\u0650\u0647\xbb\u060c \u0623\u064a: \u0623\u064e\u062d\u0645\u064e\u062f\u064f \u0627\u0644\u0644\u0647\u064e \u0639\u0644\u0649 \u0645\u0627 \u064a\u064e\u0633\u0651\u064e\u0631\u064e \u0645\u0650\u0646 \u0627\u0644\u062a\u0651\u064e\u0633\u0628\u064a\u062d\u0650 \u0648\u0627\u0644\u0637\u0651\u064e\u0627\u0639\u0627\u062a\u0650. \u0648\u0627\u0644\u062a\u0651\u064e\u0633\u0628\u064a\u062d\u064f: \u062a\u064e\u0646\u0632\u0650\u064a\u0647\u064f \u0627\u0644\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u064e\u0649 \u0639\u0646 \u0643\u0644\u0651\u0650 \u0646\u064e\u0642\u0635\u064d \u0648\u0639\u064e\u064a\u0628\u064d.","\u0648\u0627\u0644\u0630\u0651\u064f\u0646\u064f\u0648\u0628\u064f \u0627\u0644\u062a\u064a \u062a\u064f\u062d\u064e\u0637\u0651\u064f \u0628\u0627\u0644\u062a\u0651\u064e\u0633\u0628\u064a\u062d\u0650 \u0647\u064a \u0627\u0644\u0635\u0651\u064e\u063a\u0627\u0626\u0631\u064f -\u0648\u0642\u064a\u0644: \u064a\u064f\u062d\u062a\u064e\u0645\u0644\u064f \u0627\u0644\u0643\u0628\u0627\u0626\u0650\u0631\u064f- \u0627\u0644\u062a\u064a \u062a\u064e\u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0642\u064f \u0628\u0650\u062d\u064f\u0642\u0648\u0642\u0650 \u0627\u0644\u0644\u0647\u0650 \u062a\u0639\u0627\u0644\u064e\u0649 \u0644\u0627 \u0628\u0650\u062d\u064f\u0642\u0648\u0642\u0650 \u0627\u0644\u0639\u0650\u0628\u0627\u062f\u0650\u061b \u0644\u0623\u0646\u0651\u064e \u062d\u064f\u0642\u0648\u0642\u064e\u0647\u0645 \u0644\u0627 \u062a\u064e\u0646\u062d\u064e\u0637\u0651\u064f \u0625\u0644\u0651\u064e\u0627 \u0628\u0627\u0633\u062a\u0631\u0636\u0627\u0626\u0650\u0647\u0650\u0645."],t.s)
B.alO=new A.h("dhikrHadiths_","\u0641\u0636\u0644\u064f \u0633\u064f\u0628\u062d\u064e\u0627\u0646 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0628\u062d\u0645\u062f\u0650\u0647\u0650","\u0639\u064e\u0646 \u0623\u0628\u064a \u0647\u064f\u0631\u064a\u0631\u064e\u0629 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u060c \u0623\u0646\u0651\u064e \u0631\u0633\u0648\u0644\u064e \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0642\u0627\u0644\u064e: \u0645\u064e\u0646 \u0642\u0627\u0644: \u0633\u064f\u0628\u062d\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u0628\u0650\u062d\u064e\u0645\u062f\u0650\u0647\u0650\u060c \u0641\u064a \u064a\u064e\u0648\u0645\u064d \u0645\u0650\u0627\u0626\u064e\u0629\u064e \u0645\u064e\u0631\u0651\u064e\u0629\u064d\u061b \u062d\u064f\u0637\u0651\u064e\u062a \u062e\u064e\u0637\u0627\u064a\u0627\u0647\u064f \u0648\u0625\u0646 \u0643\u0627\u0646\u064e\u062a \u0645\u0650\u062b\u0644\u064e \u0632\u064e\u0628\u064e\u062f\u0650 \u0627\u0644\u0628\u064e\u062d\u0631\u0650 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aD9)
