B.aKl=s([u.e2,"\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u0650 \u064a\u064f\u062e\u0628\u0650\u0631\u064f \u062d\u064f\u0630\u064e\u064a\u0641\u0629\u064f \u0628\u0646\u064f \u0627\u0644\u064a\u064e\u0645\u0627\u0646\u0650 \u0631\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u064f\u0645\u0627 \u0623\u0646\u0651\u064e \u0627\u0644\u0645\u064f\u0646\u0627\u0641\u0650\u0642\u064a\u0646\u064e \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0628\u0639\u062f \u0639\u064e\u0647\u062f\u0650 \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u0650 \ufdfa \u0623\u0634\u064e\u062f\u0651\u064f \u0634\u064e\u0631\u0651\u064b\u0627 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0650\u0642\u064a\u0646\u064e \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0639\u0644\u0649 \u0639\u064e\u0647\u062f\u0650 \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u0650 \ufdfa\u060c \u0648\u064a\u064f\u0639\u0644\u0651\u0650\u0644\u064f \u0630\u0644\u0650\u0643\u064e \u0628\u0623\u0646\u0651\u064e\u0647\u064f\u0645 \u0643\u0627\u0646\u064f\u0648\u0627 \u064a\u064f\u0633\u0650\u0631\u0651\u0648\u0646\u064e \u0646\u0641\u0627\u0642\u064e\u0647\u0645 \u0648\u064a\u064f\u062e\u0641\u0648\u0646\u064e\u0647\u060c \u0641\u0644\u0627 \u064a\u062a\u0639\u062f\u0651\u064e\u0649 \u0634\u064e\u0631\u0651\u064f\u0647\u0645 \u0625\u0644\u0649 \u063a\u064a\u0631\u0650\u0647\u0645\u060c \u0648\u0623\u0645\u0651\u064e\u0627 \u0628\u0639\u062f \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u0650 \ufdfa \u0641\u0625\u0646\u0647\u0645 \u064a\u064e\u062c\u0647\u064e\u0631\u0648\u0646\u064e \u0628\u0647\u061b \u0641\u0647\u064f\u0645 \u0623\u0639\u0644\u0646\u0648\u0627 \u0628\u0627\u0644\u0634\u0651\u064e\u0631\u0651\u0650 \u0623\u0643\u062b\u0631\u064e \u0648\u0623\u0638\u0647\u064e\u0631\u064e \u0645\u0650\u0646 \u0633\u0627\u0628\u0650\u0642\u064a\u0647\u0650\u0645 \u0645\u0650\u0646\u064e \u0627\u0644\u0645\u0646\u0627\u0641\u0650\u0642\u064a\u0646\u064e\u060c \u063a\u064a\u0631\u064e \u0623\u0646\u0651\u064e\u0647\u0645 \u0644\u0645 \u064a\u064f\u0639\u0644\u0650\u0646\u0648\u0627 \u0627\u0644\u0643\u064f\u0641\u0631\u064e \u0635\u064e\u0631\u064a\u062d\u064b\u0627\u061b \u0644\u064a\u064f\u0638\u064e\u0646\u0651\u064e \u0623\u0646\u0651\u064e\u0647\u0645 \u0645\u064f\u0633\u0644\u0650\u0645\u0648\u0646\u064e.","\u0648\u0645\u0646 \u0635\u064f\u0648\u064e\u0631\u0650 \u0625\u0638\u0647\u0627\u0631\u0650\u0647\u0645 \u0644\u0646\u0641\u0627\u0642\u0650\u0647\u0645: \u0623\u0646\u0647\u0645 \u064a\u064e\u062c\u0647\u064e\u0631\u0648\u0646 \u0628\u0627\u0644\u0646\u0651\u0650\u0641\u0627\u0642\u0650 \u0648\u064a\u064f\u0639\u0644\u0650\u0646\u0648\u0646\u064e\u0647 \u0628\u0627\u0644\u062e\u064f\u0631\u0648\u062c\u0650 \u0639\u0644\u0649 \u0627\u0644\u062c\u064e\u0645\u0627\u0639\u0629\u0650 \u0648\u064a\u064f\u062d\u064e\u0632\u0651\u0650\u0628\u0648\u0646\u064e\u0647\u0645 \u0623\u062d\u0632\u0627\u0628\u064b\u0627\u060c \u0648\u064a\u064f\u0648\u0642\u0650\u0639\u0648\u0646 \u0627\u0644\u0634\u0651\u064e\u0631\u0651\u064e \u0628\u064a\u0646 \u0627\u0644\u0641\u0650\u0631\u064e\u0642\u0650\u060c \u0641\u064a\u062a\u0639\u062f\u0651\u064e\u0649 \u0634\u064e\u0631\u0651\u064f\u0647\u0645 \u0644\u063a\u064e\u064a\u0631\u0650\u0647\u0645.","\u0648\u0647\u0630\u0627 \u0625\u0634\u0627\u0631\u0629\u064c \u0645\u0646\u0647 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647 \u0625\u0644\u0649 \u0636\u064e\u0639\u0641\u0650 \u0627\u0644\u062d\u064e\u0642\u0651\u0650 \u0648\u0638\u064f\u0647\u0648\u0631\u0650 \u0627\u0644\u0628\u0627\u0637\u0650\u0644\u0650 \u0648\u0627\u0633\u062a\u0642\u0648\u0627\u0626\u0650\u0647\u061b \u0641\u0627\u0644\u0645\u0646\u0627\u0641\u0650\u0642\u0648\u0646 \u064a\u064e\u062e\u0634\u064e\u0648\u0646 \u0645\u0646 \u0633\u064e\u0637\u0648\u0629\u0650 \u0627\u0644\u062d\u064e\u0642\u0651\u0650\u060c \u0641\u064a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u060c \u0644\u0643\u0646 \u0625\u0630\u0627 \u0636\u064e\u0639\u064f\u0641 \u0627\u0644\u062d\u064e\u0642\u0651\u064f \u0628\u064e\u0631\u064e\u0632\u0648\u0627.","\u0648\u0641\u064a \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650: \u0627\u0644\u062a\u0651\u064e\u062d\u0630\u064a\u0631\u064f \u0645\u0650\u0646 \u0627\u0644\u0646\u0651\u064e\u0641\u0627\u0642\u0650 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0650\u0642\u064a\u0646\u064e.","\u0648\u0641\u064a\u0647: \u0639\u064e\u062f\u0645\u064f \u0645\u064f\u062a\u0627\u0628\u064e\u0639\u0629\u0650 \u0645\u064e\u0646 \u064a\u064e\u0638\u0647\u064e\u0631\u064f \u0639\u0644\u064a\u0647\u0650 \u0627\u0644\u0646\u0651\u0650\u0641\u0627\u0642\u064f \u0641\u064a \u0623\u0641\u0639\u0627\u0644\u0650\u0647\u0650 \u0627\u0644\u0628\u0627\u0637\u0650\u0644\u0629\u0650 \u0627\u0644\u062a\u064a \u064a\u064e\u0641\u0639\u064e\u0644\u064f\u0647\u0627 \u0636\u0650\u062f\u0651\u064e \u0627\u0644\u0645\u0633\u0644\u0650\u0645\u064a\u0646\u064e \u0648\u0634\u064e\u0631\u064a\u0639\u062a\u0650\u0647\u0645."],t.s)
