B.ap5=new A.h("dhulmHadiths_13","\u062d\u064f\u0631\u0645\u0629 \u062a\u0631\u0648\u0650\u064a\u0639 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0628\u0627\u0644\u0633\u0650\u0651\u0644\u0627\u062d","\u0639\u064e\u0646 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u0645\u0631 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0645\u0627\u060c \u0623\u0646\u0651\u064e \u0631\u0633\u0648\u0644\u064e \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0642\u0627\u0644\u064e: \u0645\u064e\u0646 \u062d\u064e\u0645\u064e\u0644\u064e \u0639\u0644\u064a\u0646\u0627 \u0627\u0644\u0633\u0651\u0650\u0644\u0627\u062d\u064e \u0641\u0644\u064a\u0633\u064e \u0645\u0650\u0646\u0651\u064e\u0627 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aUl)
