B.aw0=s(["\u0648\u0644\u0645 \u062a\u0633\u0644\u0645 \u0627\u0644\u062d\u0646\u064a\u0641\u064a\u0629\u064f \u0646\u0641\u0633\u064f\u0647\u0627 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641\u060c \u0641\u0642\u062f \u0627\u0628\u062a\u0639\u062f\u062a \u0628\u0639\u0636\u064f \u0645\u0639\u062a\u0642\u062f\u0627\u062a\u0647\u0627 \u0645\u0646 \u062f\u064a\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0646 \u062d\u0642\u064a\u0642\u062a\u0647\u0627\u060c \u0648\u0623\u064f\u0644\u0635\u0642 \u0628\u0647\u0627 \u0645\u0646 \u0627\u0644\u062e\u0631\u0627\u0641\u0627\u062a \u0648\u0627\u0644\u0623\u0633\u0627\u0637\u064a\u0631\u060c \u0648\u0623\u0635\u0627\u0628\u0647\u0627 \u0627\u0644\u062a\u063a\u064a\u064a\u0631\u064f \u0648\u0627\u0644\u062a\u0628\u062f\u064a\u0644\u060c \u0648\u0635\u0627\u0631 \u0627\u0644\u062d\u062c\u064f\u0651 \u0645\u0648\u0633\u0645\u064b\u0627 \u0644\u0644\u0645\u0641\u0627\u062e\u0631\u0629 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0631\u0629 \u0648\u0627\u0644\u0645\u0628\u0627\u0647\u0627\u0629\u060c \u063a\u064a\u0631 \u0623\u0646 \u0628\u0639\u0636 \u0627\u0644\u0623\u0641\u0631\u0627\u062f \u0645\u0646 \u0627\u0644\u062d\u0646\u0641\u0627\u0621 \u0638\u0644\u0651\u0648\u0627 \u064a\u064e\u0631\u0641\u064f\u0636\u0648\u0646 \u0639\u0628\u0627\u062f\u0629\u064e \u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0648\u0645\u0627 \u064a\u062a\u0639\u0644\u0642 \u0628\u0647\u0627 \u0645\u0646 \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0648\u0627\u0644\u0646\u062d\u0627\u0626\u0631 \u0648\u063a\u064a\u0631\u0647\u0627\u060c \u0648\u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0632\u064a\u062f \u0628\u0646 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0646\u064f\u0641\u064a\u0644\u060c \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0644\u0627 \u064a\u064e\u0630\u0628\u062d \u0644\u0644\u0623\u0646\u0635\u0627\u0628 \u0648\u0644\u0627 \u064a\u0623\u0643\u0644 \u0627\u0644\u0645\u064a\u062a\u0629\u064e \u0648\u0627\u0644\u062f\u0645\u060c \u0648\u0643\u0627\u0646 \u064a\u0642\u0648\u0644:","\u0623\u064e\u0631\u064e\u0628\u064b\u0651\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0623\u0645 \u0623\u0644\u0641\u064e \u0631\u0628\u061f\u061f .. \u0623\u064e\u062f\u0650\u064a\u0646\u064f \u0625\u0630\u0627 \u062a\u064e\u0642\u064e\u0633\u064e\u0651\u0645\u062a \u0627\u0644\u0623\u0645\u0648\u0631\u064f\u061f","\u0639\u064e\u0632\u0644\u062a\u064f \u0627\u0644\u0644\u0627\u062a \u0648\u0627\u0644\u0639\u0632\u0649 \u062c\u0645\u064a\u0639\u064b\u0627 .. \u0643\u0630\u0644\u0643 \u064a\u0641\u0639\u0644 \u0627\u0644\u062c\u064e\u0644\u062f\u064f \u0627\u0644\u0635\u0628\u0648\u0631\u064f","\u0641\u0644\u0627 \u0627\u0644\u0639\u0632\u0649 \u0623\u064e\u062f\u0650\u064a\u0646\u064f \u0648\u0644\u0627 \u0627\u0628\u0646\u062a\u064a\u0647\u0627 .. \u0648\u0644\u0627 \u0635\u0646\u0645\u064e\u064a \u0628\u0646\u064a \u0639\u0645\u0631\u0648 \u0623\u064e\u0632\u0648\u0631\u064f","\u0648\u0644\u0627 \u063a\u064e\u0646\u0645\u064b\u0627 \u0623\u064e\u062f\u0650\u064a\u0646\u064f \u0648\u0643\u0627\u0646 \u0631\u0628\u064b\u0651\u0627 .. \u0644\u0646\u0627 \u0641\u064a \u0627\u0644\u062f\u0647\u0631\u060c \u0625\u0630\u0627 \u062d\u0650\u0644\u0645\u064a \u064a\u0633\u064a\u0631\u064f","\u0648\u0644\u0643\u0646 \u0623\u0639\u0628\u062f \u0627\u0644\u0631\u062d\u0645\u0646 \u0631\u0628\u064a .. \u0644\u064a\u063a\u0641\u0631 \u0630\u0646\u0628\u064a\u064e \u0627\u0644\u0631\u0628\u064f\u0651 \u0627\u0644\u063a\u0641\u0648\u0631\u064f","\u0648\u0645\u0645\u0646 \u0643\u0627\u0646 \u064a\u064e\u062f\u0650\u064a\u0646 \u0628\u0634\u0631\u064a\u0639\u0629 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0639\u0644\u064a\u0647\u0645\u0627 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645 \u0642\u064f\u0633\u064f\u0651 \u0628\u0646 \u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0625\u064a\u0627\u062f\u064a\u060c \u0648\u0643\u0627\u0646 \u062e\u0637\u064a\u0628\u064b\u0627 \u062d\u0643\u064a\u0645\u064b\u0627 \u0639\u0627\u0642\u0644\u0627\u064b \u0644\u0647 \u0646\u064e\u0628\u0627\u0647\u0629\u064c \u0648\u0641\u0636\u0644\u060c \u064a\u062f\u0639\u0648 \u0625\u0644\u0649 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0648\u0639\u0628\u0627\u062f\u062a\u0647 \u0648\u062a\u0631\u0643 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646\u060c \u0648\u064a\u0624\u0645\u0646 \u0628\u0627\u0644\u0628\u0639\u062b \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0642\u062f \u0628\u064e\u0634\u064e\u0651\u0631 \u0628\u0627\u0644\u0646\u0628\u064a \ufdfa\u061b \u0641\u0642\u062f \u0631\u064e\u0648\u0649 \u0623\u0628\u0648 \u0646\u064f\u0639\u064a\u0645 \u0641\u064a \u062f\u0644\u0627\u0626\u0644 \u0627\u0644\u0646\u0628\u0648\u0629 \u0639\u0646 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0642\u0627\u0644: \xab\u0625\u0646 \u0642\u064f\u0633\u064e\u0651 \u0628\u0646 \u0633\u0627\u0639\u062f\u0629 \u0643\u0627\u0646 \u064a\u064e\u062e\u0637\u064f\u0628 \u0642\u0648\u0645\u064e\u0647 \u0641\u064a \u0633\u0648\u0642 \u0639\u064f\u0643\u0627\u0638 \u0641\u0642\u0627\u0644 \u0641\u064a \u062e\u0637\u0628\u062a\u0647: \u0633\u064a\u0639\u0644\u0645 \u062d\u0642\u064c\u0651 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0648\u062c\u0647\u060c \u0648\u0623\u0634\u0627\u0631 \u0628\u064a\u062f\u0647 \u0625\u0644\u0649 \u0645\u0643\u0629\u060c \u0642\u0627\u0644\u0648\u0627: \u0648\u0645\u0627 \u0647\u0630\u0627 \u0627\u0644\u062d\u0642\u061f \u0642\u0627\u0644: \u0631\u062c\u0644 \u0645\u0646 \u0648\u0644\u062f \u0644\u064f\u0624\u064a\u0651 \u0628\u0646 \u063a\u0627\u0644\u0628 \u064a\u064e\u062f\u0639\u0648\u0643\u0645 \u0625\u0644\u0649 \u0643\u0644\u0645\u0629 \u0627\u0644\u0625\u062e\u0644\u0627\u0635\u060c \u0648\u0639\u064a\u0634 \u0627\u0644\u0623\u0628\u062f\u060c \u0648\u0646\u0639\u064a\u0645 \u0644\u0627 \u064a\u064e\u0646\u0641\u064e\u062f\u060c \u0641\u0625\u0646 \u062f\u0639\u0627\u0643\u0645 \u0641\u0623\u062c\u064a\u0628\u0648\u0647\u060c \u0648\u0644\u0648 \u0639\u0644\u0645\u062a\u064f \u0623\u0646\u064a \u0623\u0639\u064a\u0634 \u0625\u0644\u0649 \u0645\u064e\u0628\u0639\u064e\u062b\u0647 \u0644\u0643\u0646\u062a\u064f \u0623\u0648\u0644 \u0645\u0646 \u064a\u064e\u0633\u0639\u0649 \u0625\u0644\u064a\u0647\xbb\u060c \u0648\u0642\u062f \u0623\u064e\u062f\u0631\u0643 \u0627\u0644\u0646\u0628\u064a\u064e\u0651 \ufdfa \u0648\u0645\u0627\u062a \u0642\u0628\u0644 \u0627\u0644\u0628\u0639\u062b\u0629.","\u0648\u0623\u064a\u0636\u064b\u0627 \u0643\u0627\u0646 \u0628\u0639\u0636\u064f \u0627\u0644\u0639\u0631\u0628 \u0642\u062f \u062a\u064e\u0646\u064e\u0635\u064e\u0651\u0631\u060c \u0648\u0628\u0639\u0636\u064f\u0647\u0645 \u062f\u062e\u0644 \u0641\u064a \u0627\u0644\u064a\u0647\u0648\u062f\u064a\u0629\u060c \u0623\u0645\u0627 \u0627\u0644\u0623\u063a\u0644\u0628\u064a\u0629\u064f \u0641\u0643\u0627\u0646\u062a \u062a\u0639\u0628\u062f \u0627\u0644\u0623\u0648\u062b\u0627\u0646\u064e \u0648\u0627\u0644\u0623\u0635\u0646\u0627\u0645."],t.s)
