B.aTb=s(["\u0641\u062e\u0631\u062c \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u062d\u062a\u0649 \u0642\u064e\u062f\u0650\u0645 \u0627\u0644\u0645\u0639\u0633\u0643\u0631\u060c \u0648\u0643\u0627\u0646 \u0630\u0648 \u0646\u0641\u0631 \u0635\u062f\u064a\u0642\u064b\u0627 \u0644\u0647\u060c \u0641\u0623\u062a\u0627\u0647 \u0648\u0642\u0627\u0644: \u064a\u0627 \u0630\u0627 \u0646\u0641\u0631 \u0647\u0644 \u0639\u0646\u062f\u0643\u0645 \u0645\u0646 \u063a\u0646\u0627\u0621\u064d \u0641\u064a\u0645\u0627 \u0646\u0632\u0644 \u0628\u0646\u0627\u061f \u0641\u0642\u0627\u0644: \u0645\u0627 \u063a\u0646\u0627\u0621 \u0631\u062c\u0644\u064d \u0623\u0633\u064a\u0631\u064d \u0644\u0627 \u064a\u0623\u0645\u0646 \u0623\u0646 \u064a\u064f\u0642\u062a\u0644 \u0628\u0643\u0631\u0629\u064b \u0623\u0648 \u0639\u0634\u064a\u0629\u060c \u0648\u0644\u0643\u0646 \u0633\u0623\u0628\u0639\u062b \u0644\u0643 \u0625\u0644\u0649 \u0623\u064f\u0646\u064a\u0633 \u0633\u0627\u0626\u0633 \u0627\u0644\u0641\u064a\u0644 \u0641\u0622\u0645\u0631\u0647 \u0623\u0646 \u064a\u0635\u0646\u0639 \u0644\u0643 \u0639\u0646\u062f \u0627\u0644\u0645\u0644\u0643 \u0645\u0627 \u0627\u0633\u062a\u0637\u0627\u0639 \u0645\u0646 \u062e\u064a\u0631\u060c \u0648\u064a\u064f\u0639\u0638\u0650\u0651\u0645 \u062e\u064e\u0637\u0631\u0643 \u0648\u0645\u0646\u0632\u0644\u062a\u0643 \u0639\u0646\u062f\u0647\u060c \u0641\u0623\u0631\u0633\u0644 \u0625\u0644\u0649 \u0623\u064f\u0646\u064a\u0633 \u0641\u0642\u0627\u0644: \u0625\u0646 \u0647\u0630\u0627 \u0633\u064a\u062f \u0642\u0631\u064a\u0634 \u0648\u0635\u0627\u062d\u0628 \u0639\u064a\u0646 \u0645\u0643\u0629 \u0627\u0644\u0630\u064a \u064a\u064f\u0637\u0639\u0645 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u0627\u0644\u0633\u0647\u0644 \u0648\u0627\u0644\u0648\u062d\u0648\u0634 \u0641\u064a \u0627\u0644\u062c\u0628\u0627\u0644\u060c \u0648\u0642\u062f \u0623\u0635\u0627\u0628 \u0644\u0647 \u0627\u0644\u0645\u0644\u0643 \u0645\u0627\u0626\u062a\u064e\u064a \u0628\u0639\u064a\u0631\u060c \u0641\u0625\u0646 \u0627\u0633\u062a\u0637\u0639\u062a \u0623\u0646 \u062a\u0646\u0641\u0639\u0647 \u0641\u0627\u0646\u0641\u0639\u0647 \u0641\u0625\u0646\u0647 \u0635\u062f\u064a\u0642 \u0644\u064a.","\u0641\u062f\u062e\u0644 \u0623\u064f\u0646\u064a\u0633 \u0639\u0644\u0649 \u0623\u0628\u0631\u0647\u0629 \u0648\u0642\u0627\u0644: \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0644\u0643 \u0647\u0630\u0627 \u0633\u064a\u062f \u0642\u0631\u064a\u0634 \u0648\u0635\u0627\u062d\u0628 \u0639\u064a\u0646 \u0645\u0643\u0629 \u0627\u0644\u0630\u064a \u064a\u064f\u0637\u0639\u0645 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u0627\u0644\u0633\u0647\u0644 \u0648\u0627\u0644\u0648\u062d\u0648\u0634 \u0641\u064a \u0627\u0644\u062c\u0628\u0627\u0644\u060c \u064a\u0633\u062a\u0623\u0630\u0646 \u0639\u0644\u064a\u0643 \u0648\u0642\u062f \u062c\u0627\u0621\u0643 \u063a\u064a\u0631 \u0646\u0627\u0635\u0628\u064d \u0644\u0643 \u0648\u0644\u0627 \u0645\u062e\u0627\u0644\u0641\u064d \u0639\u0644\u064a\u0643\u060c \u0641\u0623\u064e\u0630\u0650\u0646 \u0644\u0647\u060c \u0648\u0643\u0627\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0631\u062c\u0644\u0627\u064b \u0639\u0638\u064a\u0645\u064b\u0627 \u062c\u0633\u064a\u0645\u064b\u0627 \u0648\u0633\u064a\u0645\u064b\u0627\u060c \u0641\u0644\u0645\u0627 \u0631\u0622\u0647 \u0623\u0628\u0631\u0647\u0629\u064f \u0639\u0638\u064e\u0651\u0645\u0647 \u0648\u0623\u0643\u0631\u0645\u0647\u060c \u0648\u0643\u0631\u0647 \u0623\u0646 \u064a\u062c\u0644\u0633 \u0645\u0639\u0647 \u0639\u0644\u0649 \u0633\u0631\u064a\u0631\u0647 \u0648\u0623\u0646 \u064a\u062c\u0644\u0633 \u062a\u062d\u062a\u0647\u060c \u0641\u0647\u0628\u0637 \u0625\u0644\u0649 \u0627\u0644\u0628\u0633\u0627\u0637 \u0641\u062c\u0644\u0633 \u0639\u0644\u064a\u0647 \u0645\u0639\u0647.","\u0641\u0642\u0627\u0644 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628: \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0644\u0643 \u0625\u0646\u0643 \u0642\u062f \u0623\u0635\u0628\u062a\u064e \u0644\u064a \u0645\u0627\u0644\u0627\u064b \u0639\u0638\u064a\u0645\u064b\u0627 \u0641\u0627\u0631\u062f\u062f\u0647 \u0639\u0644\u064a\u064e\u0651\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0623\u0628\u0631\u0647\u0629: \u0644\u0642\u062f \u0623\u0639\u062c\u0628\u062a\u0646\u064a \u062d\u064a\u0646 \u0631\u0623\u064a\u062a\u0643 \u0648\u0644\u0642\u062f \u0632\u0647\u062f\u062a\u064f \u0641\u064a\u0643\u060c \u0642\u0627\u0644: \u0648\u0644\u0645\u061f \u0642\u0627\u0644: \u062c\u0626\u062a \u0625\u0644\u0649 \u0628\u064a\u062a\u064d \u0647\u0648 \u062f\u064a\u0646\u0643 \u0648\u062f\u064a\u0646 \u0622\u0628\u0627\u0626\u0643 \u0648\u0639\u0650\u0635\u0645\u062a\u0643\u0645 \u0648\u0645\u0646\u0639\u062a\u0643\u0645 \u0641\u0623\u0647\u062f\u0645\u0647 \u0641\u0644\u0645 \u062a\u064f\u0643\u0644\u0645\u0646\u064a \u0641\u064a\u0647\u060c \u0648\u062a\u064f\u0643\u0644\u0645\u0646\u064a \u0641\u064a \u0645\u0627\u0626\u062a\u064e\u064a \u0628\u0639\u064a\u0631 \u0644\u0643\u061f \u0641\u0642\u0627\u0644 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628: \u0623\u0646\u0627 \u0631\u0628\u064f\u0651 \u0647\u0630\u0647 \u0627\u0644\u0625\u0628\u0644\u060c \u0648\u0644\u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u062a \u0631\u0628\u064c\u0651 \u0633\u064a\u0645\u0646\u0639\u0647\u060c \u0642\u0627\u0644: \u0645\u0627 \u0643\u0627\u0646 \u0644\u064a\u0645\u0646\u0639\u0647 \u0645\u0646\u064a\u060c \u0642\u0627\u0644: \u0641\u0623\u0646\u062a \u0648\u0630\u0627\u0643\u060c \u0641\u0623\u0645\u0631 \u0628\u0625\u0628\u0644\u0647 \u0641\u0631\u064f\u062f\u064e\u0651\u062a \u0639\u0644\u064a\u0647."],t.s)
