B.aUC=s(["\u062b\u0645 \u062e\u0631\u062c \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0641\u0623\u062e\u0628\u0631 \u0642\u0631\u064a\u0634\u064b\u0627 \u0627\u0644\u062e\u0628\u0631 \u0648\u0623\u0645\u0631\u0647\u0645 \u0623\u0646 \u064a\u062a\u0641\u0631\u0642\u0648\u0627 \u0641\u064a \u0627\u0644\u0634\u0650\u0651\u0639\u0627\u0628\u060c \u0648\u0623\u0635\u0628\u062d \u0623\u0628\u0631\u0647\u0629 \u0628\u0627\u0644\u0645\u063a\u0645\u0633 \u0642\u062f \u062a\u0647\u064a\u064e\u0651\u0623 \u0644\u0644\u062f\u062e\u0648\u0644 \u0648\u0639\u0628\u064e\u0651\u0623 \u062c\u064a\u0634\u0647\u060c \u0648\u0642\u0631\u064e\u0651\u0628 \u0641\u064a\u0644\u0647 \u0648\u062d\u0645\u064e\u0651\u0644\u0647 \u0645\u0627 \u0623\u0631\u0627\u062f \u0648\u0647\u0648 \u0642\u0627\u0626\u0645\u060c \u0641\u0644\u0645\u0627 \u062d\u0631\u064e\u0651\u0643\u0648\u0647 \u0648\u0642\u0641 \u0648\u0643\u0627\u062f \u064a\u064e\u0631\u0632\u064f\u0645 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0641\u064a\u0628\u0631\u0643\u060c \u0641\u0636\u0631\u0628\u0648\u0647 \u0628\u0627\u0644\u0645\u0639\u0648\u0644 \u0641\u064a \u0631\u0623\u0633\u0647 \u0641\u0623\u0628\u0649\u060c \u0648\u0623\u062f\u062e\u0644\u0648\u0627 \u0645\u062d\u0627\u062c\u0646\u064e\u0647\u0645 \u062a\u062d\u062a \u0645\u064e\u0631\u0627\u0642\u0650\u0651\u0647 \u0648\u0645\u0631\u0627\u0641\u0642\u0647 \u0641\u0623\u0628\u0649\u060c \u0641\u0648\u062c\u064e\u0651\u0647\u0648\u0647 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u0646 \u0641\u0647\u064e\u0631\u0648\u0644\u060c \u0641\u0635\u0631\u0641\u0648\u0647 \u0625\u0644\u0649 \u0627\u0644\u062d\u0631\u0645 \u0641\u0648\u0642\u0641.","\u0648\u0644\u062d\u0642 \u0627\u0644\u0641\u064a\u0644\u064f \u0628\u062c\u0628\u0644 \u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u062c\u0628\u0627\u0644\u060c \u0641\u0623\u0631\u0633\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0637\u064a\u0631 \u0645\u0646 \u0627\u0644\u0628\u062d\u0631 \u0643\u0627\u0644\u0628\u064e\u0644\u064e\u0633\u0627\u0646 -\u0627\u0644\u0632\u0631\u0627\u0632\u064a\u0631- \u0645\u0639 \u0643\u0644 \u0637\u064a\u0631 \u062b\u0644\u0627\u062b\u0629\u064f \u0623\u062d\u062c\u0627\u0631: \u062d\u062c\u0631\u0627\u0646 \u0641\u064a \u0631\u062c\u0644\u064a\u0647 \u0648\u062d\u062c\u0631 \u0641\u064a \u0645\u0646\u0642\u0627\u0631\u0647\u060c \u062a\u062d\u0645\u0644 \u0623\u0645\u062b\u0627\u0644 \u0627\u0644\u062d\u0650\u0645\u064e\u0651\u0635 \u0648\u0627\u0644\u0639\u062f\u0633\u060c \u0641\u0625\u0630\u0627 \u063a\u064e\u0634\u0650\u064a\u0646 \u0627\u0644\u0642\u0648\u0645\u064e \u0623\u0631\u0633\u0644\u0646\u0647\u0627 \u0639\u0644\u064a\u0647\u0645\u060c \u0641\u0644\u0645 \u062a\u064f\u0635\u0650\u0628 \u062a\u0644\u0643 \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0623\u062d\u062f\u064b\u0627 \u0625\u0644\u0627 \u0647\u0644\u0643\u060c \u0648\u0644\u064a\u0633 \u0643\u0644 \u0627\u0644\u0642\u0648\u0645 \u0623\u064f\u0635\u064a\u0628\u060c \u0648\u0630\u0644\u0643 \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0623\u064e\u0644\u064e\u0645 \u062a\u064e\u0631\u064e \u0643\u064e\u064a\u0641\u064e \u0641\u064e\u0639\u064e\u0644\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0628\u0650\u0623\u064e\u0635\u062d\u064e\u0627\u0628\u0650 \u0627\u0644\u0641\u0650\u064a\u0644\u0650 \u06dd \u0623\u064e\u0644\u064e\u0645 \u064a\u064e\u062c\u0639\u064e\u0644 \u0643\u064e\u064a\u062f\u064e\u0647\u064f\u0645 \u0641\u0650\u064a \u062a\u064e\u0636\u0644\u0650\u064a\u0644\u064d \u06dd \u0648\u064e\u0623\u064e\u0631\u0633\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0647\u0650\u0645 \u0637\u064e\u064a\u0631\u064b\u0627 \u0623\u064e\u0628\u064e\u0627\u0628\u0650\u064a\u0644\u064e \u06dd \u062a\u064e\u0631\u0645\u0650\u064a\u0647\u0650\u0645 \u0628\u0650\u062d\u0650\u062c\u064e\u0627\u0631\u064e\u0629\u064d \u0645\u0651\u0650\u0646 \u0633\u0650\u062c\u0651\u0650\u064a\u0644\u064d \u06dd \u0641\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0647\u064f\u0645 \u0643\u064e\u0639\u064e\u0635\u0641\u064d \u0645\u0651\u064e\u0623\u0643\u064f\u0648\u0644\u064d\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0641\u064a\u0644","\u0648\u0628\u0639\u062b \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0623\u0628\u0631\u0647\u0629 \u062f\u0627\u0621\u064b \u0641\u064a \u062c\u0633\u062f\u0647\u060c \u0641\u0631\u062c\u0639\u0648\u0627 \u0633\u0650\u0631\u0627\u0639\u064b\u0627 \u064a\u062a\u0633\u0627\u0642\u0637\u0648\u0646 \u0641\u064a \u0643\u0644 \u0628\u0644\u062f\u060c \u0648\u062c\u0639\u0644 \u0623\u0628\u0631\u0647\u0629\u064f \u062a\u062a\u0633\u0627\u0642\u0637 \u0623\u0646\u0627\u0645\u0644\u0647\u060c \u0643\u0644\u0645\u0627 \u0633\u0642\u0637\u062a \u0623\u0646\u0645\u0644\u0629\u064c \u0623\u062a\u0628\u0639\u062a\u0647\u0627 \u0645\u0650\u062f\u064e\u0651\u0629\u064c \u0645\u0646 \u0642\u064a\u062d\u064d \u0648\u062f\u0645\u060c \u0641\u0627\u0646\u062a\u0647\u0649 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u0646 \u0648\u0647\u0648 \u0645\u062b\u0644 \u0641\u0631\u062e \u0627\u0644\u0637\u064a\u0631 \u0645\u0639 \u0645\u0646 \u0628\u0642\u064a \u0645\u0646 \u0623\u0635\u062d\u0627\u0628\u0647\u060c \u062b\u0645 \u0645\u0627\u062a.","\u0648\u0630\u0643\u0631 \u0627\u0628\u0646 \u0625\u0633\u062d\u0627\u0642 \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u0641\u064a \u0633\u064a\u0631\u062a\u0647\u060c \u0643\u0645\u0627 \u0646\u0642\u0644\u0647 \u0627\u0628\u0646 \u0647\u0634\u0627\u0645 \u0639\u0646\u0647\u060c \u0623\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0623\u062e\u0630 \u0628\u062d\u0644\u0642\u0629 \u0628\u0627\u0628 \u0627\u0644\u0643\u0639\u0628\u0629 \u0648\u0642\u0627\u0645 \u0645\u0639\u0647 \u0646\u0641\u0631\u064c \u0645\u0646 \u0642\u0631\u064a\u0634 \u064a\u062f\u0639\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u064a\u0633\u062a\u0646\u0635\u0631\u0648\u0646\u0647 \u0639\u0644\u0649 \u0623\u0628\u0631\u0647\u0629 \u0648\u062c\u0646\u062f\u0647\u060c \u0641\u0642\u0627\u0644 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0648\u0647\u0648 \u0622\u062e\u0630\u064c \u0628\u062d\u0644\u0642\u0629 \u0628\u0627\u0628 \u0627\u0644\u0643\u0639\u0628\u0629:","\u0644\u0627 \u0647\u064f\u0645\u064e\u0651 \u0625\u0646 \u0627\u0644\u0639\u0628\u062f \u064a\u064e\u0645\u0640\u0646\u0639 .. \u0631\u064e\u062d\u0644\u0647 \u0641\u0627\u0645\u0646\u0639 \u062d\u0650\u0644\u0627\u0644\u064e\u0643","\u0644\u0627 \u064a\u064e\u063a\u0644\u0650\u0628\u064e\u0646\u064e\u0651 \u0635\u0644\u064a\u0628\u064f\u0647\u0645 .. \u0648\u0645\u0650\u062d\u0627\u0644\u064f\u0647\u0645 \u063a\u064e\u062f\u0648\u064b\u0627 \u0645\u0650\u062d\u0627\u0644\u064e\u0643","\u0625\u0646 \u0643\u0646\u062a\u064e \u062a\u0627\u0631\u0643\u064e\u0647\u0645 \u0648\u0642\u0650\u0628\u0640\u0640\u0644\u062a\u064e\u0646\u0627 .. \u0641\u0623\u0645\u0631\u064c \u0645\u0627 \u0628\u064e\u062f\u0627 \u0644\u064e\u0643","\u062b\u0645 \u0623\u0631\u0633\u0644 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u062d\u0644\u0642\u0629\u064e \u0628\u0627\u0628 \u0627\u0644\u0643\u0639\u0628\u0629 \u0648\u0627\u0646\u0637\u0644\u0642 \u0647\u0648 \u0648\u0645\u0646 \u0645\u0639\u0647 \u0645\u0646 \u0642\u0631\u064a\u0634 \u0625\u0644\u0649 \u0634\u064e\u0639\u064e\u0641 \u0627\u0644\u062c\u0628\u0627\u0644 \u064a\u062a\u062d\u0631\u0632\u0648\u0646 \u0641\u064a\u0647\u0627\u060c \u064a\u0646\u062a\u0638\u0631\u0648\u0646 \u0645\u0627 \u0623\u0628\u0631\u0647\u0629 \u0641\u0627\u0639\u0644\u064c \u0628\u0645\u0643\u0629 \u0625\u0630\u0627 \u062f\u062e\u0644\u0647\u0627."],t.s)
