B.aAt=s(["\u0623\u062e\u0628\u0631\u064e \u0633\u0644\u0645\u0627\u0646\u064f \u0627\u0644\u0641\u0627\u0631\u0633\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u064a \u0642\u0635\u0629 \u0625\u0633\u0644\u0627\u0645\u0647 \u0627\u0644\u0645\u0634\u0647\u0648\u0631\u0629 \u0639\u0646 \u0631\u0627\u0647\u0628\u0650 \u0639\u0645\u064f\u0651\u0648\u0631\u064a\u064e\u0651\u0629 \u062d\u064a\u0646 \u062d\u0636\u0631\u062a\u0647 \u0627\u0644\u0645\u0646\u064a\u0629\u060c \u0641\u0642\u0627\u0644 \u0644\u0633\u0644\u0645\u0627\u0646: \xab\u0625\u0646\u0647 \u0642\u062f \u0623\u0638\u0644\u064e\u0651 \u0632\u0645\u0627\u0646\u064f \u0646\u0628\u064a\u064d\u0651 \u0645\u0628\u0639\u0648\u062b\u064d \u0628\u062f\u064a\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\xbb\u060c \u064a\u062e\u0631\u062c\u064f \u0628\u0623\u0631\u0636 \u0627\u0644\u0639\u0631\u0628\u060c \u0645\u064f\u0647\u0627\u062c\u064e\u0631\u064f\u0647 \u0625\u0644\u0649 \u0623\u0631\u0636 \u0628\u064a\u0646 \u062d\u064e\u0631\u064e\u0651\u062a\u064a\u0646 \u0628\u064a\u0646\u0647\u0645\u0627 \u0646\u062e\u0644\u060c \u0628\u0647 \u0639\u0644\u0627\u0645\u0627\u062a\u064c \u0644\u0627 \u062a\u062e\u0641\u0649\u060c \u064a\u0623\u0643\u0644\u064f \u0627\u0644\u0647\u062f\u064a\u0629\u064e \u0648\u0644\u0627 \u064a\u0623\u0643\u0644 \u0627\u0644\u0635\u062f\u0642\u0629\u060c \u0628\u064a\u0646 \u0643\u062a\u0641\u064a\u0647 \u062e\u0627\u062a\u0645\u064f \u0627\u0644\u0646\u0628\u0648\u0629\u060c \u0641\u0625\u0646 \u0627\u0633\u062a\u0637\u0639\u062a\u064e \u0623\u0646 \u062a\u0644\u062d\u0642 \u0628\u062a\u0644\u0643 \u0627\u0644\u0628\u0644\u0627\u062f \u0641\u0627\u0641\u0639\u0644.","\u062b\u0645 \u0642\u0635\u064e\u0651 \u0633\u0644\u0645\u0627\u0646\u064f \u062e\u0628\u0631\u064e \u0642\u062f\u0648\u0645\u0647 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u0627\u0633\u062a\u0631\u0642\u0627\u0642\u0650\u0647 \u0648\u0644\u0642\u0627\u0626\u0650\u0647 \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062d\u064a\u0646 \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0648\u0625\u0647\u062f\u0627\u0626\u0650\u0647 \u0644\u0647 \u0637\u0639\u0627\u0645\u064b\u0627 \u0639\u0644\u0649 \u0623\u0646\u0647 \u0635\u062f\u0642\u0629 \u0641\u0644\u0645 \u064a\u0623\u0643\u0644 \u0645\u0646\u0647 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa\u060c \u062b\u0645 \u0625\u0647\u062f\u0627\u0626\u0650\u0647 \u0644\u0647 \u0637\u0639\u0627\u0645\u064b\u0627 \u0639\u0644\u0649 \u0623\u0646\u0647 \u0647\u062f\u064a\u0629 \u0641\u0623\u0643\u0644\u064e \u0645\u0646\u0647\u060c \u062b\u0645 \u0631\u0624\u064a\u062a\u0650\u0647 \u062e\u0627\u062a\u0645\u064e \u0627\u0644\u0646\u0628\u0648\u0629 \u0628\u064a\u0646 \u0643\u062a\u0641\u064a\u0647\u060c \u0648\u0625\u0633\u0644\u0627\u0645\u0650\u0647 \u0639\u0644\u0649 \u0623\u062b\u0631\u0650 \u0630\u0644\u0643.","\u0648\u0645\u0646 \u0630\u0644\u0643 \u0625\u062e\u0628\u0627\u0631\u064f \u0623\u062d\u0628\u0627\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0631\u062c\u0627\u0644\u0627\u062a\u0647\u0627 \u0628\u0642\u064f\u0631\u0628 \u0645\u0628\u0639\u062b\u0647 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0645\u0646\u0647\u0627 \u0642\u0635\u0629\u064f \u0623\u0628\u064a \u0627\u0644\u062a\u064a\u0647\u0627\u0646 \u0627\u0644\u0630\u064a \u062e\u0631\u062c\u064e \u0645\u0646 \u0628\u0644\u0627\u062f \u0627\u0644\u0634\u0627\u0645 \u0648\u0646\u0632\u0644\u064e \u0641\u064a \u0628\u0646\u064a \u0642\u0631\u064a\u0638\u0629 \u062b\u0645 \u062a\u064f\u0648\u0641\u0650\u0651\u064a\u064e \u0642\u0628\u0644 \u0627\u0644\u0628\u0639\u062b\u0629 \u0627\u0644\u0646\u0628\u0648\u064a\u0629 \u0628\u0633\u0646\u062a\u064a\u0646\u060c \u0641\u0644\u0645\u0627 \u062d\u0636\u0631\u062a\u0647 \u0627\u0644\u0648\u0641\u0627\u0629\u064f \u0642\u0627\u0644 \u0644\u0628\u0646\u064a \u0642\u0631\u064a\u0638\u0629: \u064a\u0627 \u0645\u0639\u0634\u0631\u064e \u064a\u0647\u0648\u062f\u060c \u0645\u0627 \u062a\u0631\u0648\u0646\u0647 \u0623\u062e\u0631\u062c\u0646\u064a \u0645\u0646 \u0623\u0631\u0636 \u0627\u0644\u062e\u0645\u0631 \u0648\u0627\u0644\u062e\u0645\u064a\u0631 -\u0627\u0644\u0634\u0627\u0645- \u0625\u0644\u0649 \u0623\u0631\u0636 \u0627\u0644\u0628\u0624\u0633 \u0648\u0627\u0644\u062c\u0648\u0639 -\u064a\u0639\u0646\u064a \u0627\u0644\u062d\u062c\u0627\u0632-\u061f \u0642\u0627\u0644\u0648\u0627: \u0623\u0646\u062a\u064e \u0623\u0639\u0644\u0645\u060c \u0642\u0627\u0644: \u0625\u0646\u064a \u0642\u062f\u0650\u0645\u062a\u064f \u0647\u0630\u0647 \u0627\u0644\u0628\u0644\u062f\u0629\u064e \u0623\u062a\u0648\u0643\u064e\u0651\u0641 -\u0623\u0646\u062a\u0638\u0631- \u062e\u0631\u0648\u062c\u064e \u0646\u0628\u064a\u064d\u0651 \u0642\u062f \u0623\u0638\u0644\u064e\u0651 \u0632\u0645\u0627\u0646\u064f\u0647\u060c \u0648\u0643\u0646\u062a\u064f \u0623\u0631\u062c\u0648 \u0623\u0646 \u064a\u064f\u0628\u0639\u064e\u062b\u064e \u0641\u0623\u062a\u064e\u0651\u0628\u0650\u0639\u064e\u0647.","\u0648\u0642\u062f \u0634\u0627\u0639\u064e \u062d\u062f\u064a\u062b\u064f \u0630\u0644\u0643 \u0648\u0627\u0646\u062a\u0634\u0631 \u0628\u064a\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u063a\u064a\u0631\u0647\u0645 \u062d\u062a\u0649 \u0628\u0644\u063a\u064e \u062f\u0631\u062c\u0629\u064e \u0627\u0644\u0642\u0637\u0639 \u0639\u0646\u062f\u0647\u0645\u060c \u0648\u0628\u0646\u0627\u0621\u064b \u0639\u0644\u064a\u0647 \u0643\u0627\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0623\u0647\u0644 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0627\u0644\u0645\u0646\u0648\u0631\u0629: \u0625\u0646\u0647 \u0642\u062f \u062a\u0642\u0627\u0631\u0628\u064e \u0632\u0645\u0627\u0646\u064f \u0646\u0628\u064a\u064d\u0651 \u064a\u064f\u0628\u0639\u064e\u062b\u064f \u0627\u0644\u0622\u0646\u060c \u0646\u0642\u062a\u0644\u064f\u0643\u0645 \u0645\u0639\u0647 \u0642\u062a\u0644\u064e \u0639\u0627\u062f\u064d \u0648\u0625\u0631\u064e\u0645\u060c \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0627\u0644\u062d\u062f\u064a\u062b\u064f \u0633\u0628\u0628\u064b\u0627 \u0641\u064a \u0625\u0633\u0644\u0627\u0645 \u0631\u062c\u0627\u0644\u064d \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u0648\u0642\u062f \u0642\u0627\u0644\u0648\u0627: \xab\u0625\u0646\u0645\u0627 \u062f\u0639\u0627\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u0639 \u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0647\u062f\u0627\u0647\u060c \u0644\u0645\u0627 \u0643\u0646\u0627 \u0646\u0633\u0645\u0639\u064f \u0645\u0646 \u0631\u062c\u0627\u0644 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0643\u0646\u0627 \u0623\u0647\u0644\u064e \u0634\u0631\u0643\u064d \u0623\u0635\u062d\u0627\u0628\u064e \u0623\u0648\u062b\u0627\u0646\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0623\u0647\u0644\u064e \u0643\u062a\u0627\u0628\u064d \u0639\u0646\u062f\u0647\u0645 \u0639\u0644\u0645\u064c \u0644\u064a\u0633 \u0644\u0646\u0627\u060c \u0648\u0643\u0627\u0646\u062a \u0644\u0627 \u062a\u0632\u0627\u0644 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646\u0647\u0645 \u0634\u0631\u0648\u0631\u060c \u0641\u0625\u0630\u0627 \u0646\u0650\u0644\u0646\u0627 \u0645\u0646\u0647\u0645 \u0628\u0639\u0636 \u0645\u0627 \u064a\u0643\u0631\u0647\u0648\u0646 \u0642\u0627\u0644\u0648\u0627 \u0644\u0646\u0627: \u0625\u0646\u0647 \u062a\u0642\u0627\u0631\u0628\u064e \u0632\u0645\u0627\u0646\u064f \u0646\u0628\u064a\u064d\u0651 \u064a\u064f\u0628\u0639\u064e\u062b\u064f \u0627\u0644\u0622\u0646\u060c \u0646\u0642\u062a\u0644\u064f\u0643\u0645 \u0645\u0639\u0647 \u0642\u062a\u0644\u064e \u0639\u0627\u062f\u064d \u0648\u0625\u0631\u064e\u0645\xbb.","\u0648\u0642\u062f \u0642\u0627\u0644 \u0647\u0650\u0631\u064e\u0642\u0644\u064f \u0645\u0644\u0643\u064f \u0627\u0644\u0631\u0648\u0645 \u0639\u0646\u062f\u0645\u0627 \u0627\u0633\u062a\u0644\u0645\u064e \u0631\u0633\u0627\u0644\u0629\u064e \u0627\u0644\u0646\u0628\u064a \ufdfa: \xab\u0648\u0642\u062f \u0643\u0646\u062a\u064f \u0623\u0639\u0644\u0645\u064f \u0623\u0646\u0647 \u062e\u0627\u0631\u062c\u060c \u0644\u0645 \u0623\u0643\u0646 \u0623\u0638\u0646\u064f\u0651 \u0623\u0646\u0647 \u0645\u0646\u0643\u0645\xbb."],t.s)
