B.awh=s(["\u0648\u0641\u064a \u062d\u062f\u064a\u062b \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627\u060c \u0623\u0646 \u0623\u0648\u0644 \u0645\u0627 \u0628\u064f\u062f\u0626 \u0628\u0647 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u0627\u0644\u0648\u062d\u064a \u0627\u0644\u0631\u0624\u064a\u0627 \u0627\u0644\u0635\u0627\u0644\u062d\u0629\u060c \u0648\u062a\u0633\u0645\u0649 \u0623\u062d\u064a\u0627\u0646\u0627\u064b \u0628\u0627\u0644\u0631\u0624\u064a\u0627 \u0627\u0644\u0635\u0627\u062f\u0642\u0629\u060c \u0648\u0627\u0644\u0645\u0631\u0627\u062f \u0628\u0647\u0627 \u0631\u0624\u0649 \u062c\u0645\u064a\u0644\u0629 \u064a\u064e\u0646\u0634\u0631\u062d \u0644\u0647\u0627 \u0627\u0644\u0635\u062f\u0631 \u0648\u062a\u064e\u0632\u0643\u0648 \u0628\u0647\u0627 \u0627\u0644\u0631\u0648\u062d\u060c \u0648\u0644\u0639\u0644 \u0627\u0644\u062d\u0643\u0645\u0629 \u0645\u0646 \u0627\u0628\u062a\u062f\u0627\u0621 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0631\u0633\u0648\u0644\u064e\u0647 \ufdfa \u0628\u0627\u0644\u0648\u062d\u064a \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0645 \u0623\u0646\u0647 \u0644\u0648 \u0623\u062a\u0627\u0647 \u0627\u0644\u0645\u0644\u0643\u064f \u0641\u062c\u0623\u0629\u064b \u0648\u0644\u0645 \u064a\u0633\u0628\u0642 \u0644\u0647 \u0623\u0646 \u0631\u0623\u0649 \u0645\u0644\u0643\u0627\u064b \u0645\u0646 \u0642\u0628\u0644\u060c \u0641\u0642\u062f \u064a\u0635\u064a\u0628\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u0641\u0632\u0639 \u0641\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u064a\u062a\u0644\u0642\u0649 \u0645\u0646\u0647 \u0634\u064a\u0626\u0627\u064b\u060c \u0641\u0627\u0642\u062a\u0636\u062a \u062d\u0643\u0645\u0629\u064f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0646 \u064a\u0623\u062a\u064a\u0647 \u0627\u0644\u0648\u062d\u064a \u0623\u0648\u0644\u0627\u064b \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0645 \u0644\u064a\u062a\u062f\u0631\u0628 \u0639\u0644\u064a\u0647 \u0648\u064a\u0639\u062a\u0627\u062f\u0647\u060c \u0648\u0627\u0644\u0631\u0624\u064a\u0627 \u0627\u0644\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u062c\u0632\u0621\u064c \u0645\u0646 \u0633\u062a\u0629 \u0648\u0623\u0631\u0628\u0639\u064a\u0646 \u062c\u0632\u0621\u0627\u064b \u0645\u0646 \u0627\u0644\u0646\u0628\u0648\u0629 \u0643\u0645\u0627 \u0648\u0631\u062f \u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b \u0627\u0644\u0634\u0631\u064a\u0641\u060c \u0648\u0642\u062f \u0642\u0627\u0644 \u0627\u0644\u0639\u0644\u0645\u0627\u0621: \u0643\u0627\u0646\u062a \u0645\u062f\u0629 \u0627\u0644\u0631\u0624\u064a\u0627 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0633\u062a\u0629 \u0623\u0634\u0647\u0631 \u0630\u0643\u0631\u0647 \u0627\u0644\u0628\u064a\u0647\u0642\u064a\u060c \u0648\u0644\u0645 \u064a\u064e\u0646\u0632\u0644 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0641\u064a \u0627\u0644\u0646\u0648\u0645 \u0628\u0644 \u0646\u0632\u0644 \u0643\u0644\u0647 \u064a\u0642\u0638\u0629\u064b.","\u0648\u0627\u0644\u0631\u0624\u064a\u0627 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0645\u0646 \u0627\u0644\u0628\u0634\u0631\u0649 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0641\u0642\u062f \u0648\u0631\u062f \u0639\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0642\u0648\u0644\u0647: \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633\u060c \u0625\u0646\u0647 \u0644\u0645 \u064a\u0628\u0642 \u0645\u0646 \u0645\u0628\u0634\u0631\u0627\u062a \u0627\u0644\u0646\u0628\u0648\u0629 \u0625\u0644\u0627 \u0627\u0644\u0631\u0624\u064a\u0627 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u064a\u0631\u0627\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645 \u0623\u0648 \u062a\u064f\u0631\u0649 \u0644\u0647\u060c \u0641\u0643\u0627\u0646 \ufdfa \u0642\u0628\u0644 \u0646\u0632\u0648\u0644 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0644\u064a\u0647 \u0628\u0627\u0644\u0648\u062d\u064a \u0641\u064a \u063a\u0627\u0631 \u062d\u0631\u0627\u0621 \u064a\u0631\u0649 \u0627\u0644\u0631\u0624\u0649 \u0627\u0644\u062c\u0645\u064a\u0644\u0629 \u0641\u064a\u0635\u062d\u0648 \u0645\u0646\u0634\u0631\u062d\u064e \u0627\u0644\u0635\u062f\u0631\u060c \u0645\u062a\u0641\u062a\u062d\u064e \u0627\u0644\u0646\u0641\u0633 \u0644\u0643\u0644 \u0645\u0627 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0645\u0646 \u062c\u0645\u0627\u0644\u060c \u0648\u0642\u062f \u0623\u062c\u0645\u0639\u062a \u0627\u0644\u0631\u0648\u0627\u064a\u0627\u062a \u0645\u0646 \u062d\u062f\u064a\u062b \u0628\u062f\u0621 \u0627\u0644\u0648\u062d\u064a \u0623\u0646 \u0623\u0648\u0644 \u0645\u0627 \u0628\u064f\u062f\u0626 \u0628\u0647 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u0627\u0644\u0648\u062d\u064a \u0627\u0644\u0631\u0624\u064a\u0627 \u0627\u0644\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u0635\u0627\u0644\u062d\u0629\u060c \u064a\u0631\u0627\u0647\u0627 \u0641\u064a \u0627\u0644\u0646\u0648\u0645 \u0641\u062a\u062c\u064a\u0621 \u0641\u064a \u0627\u0644\u064a\u0642\u0638\u0629 \u0643\u0627\u0645\u0644\u0629\u064b \u0648\u0627\u0636\u062d\u0629\u064b \u0643\u0645\u0627 \u0631\u0622\u0647\u0627\u060c \u0644\u0627 \u064a\u063a\u064a\u0628 \u0639\u0644\u064a\u0647 \u0645\u0646\u0647\u0627 \u0634\u064a\u0621\u060c \u0643\u0623\u0646\u0645\u0627 \u0646\u064f\u0642\u0634\u062a \u0641\u064a \u0642\u0644\u0628\u0647 \u0648\u0639\u0642\u0644\u0647\u060c \u0648\u0642\u062f \u0634\u0628\u064e\u0651\u0647\u062a \u0627\u0644\u0633\u064a\u062f\u0629 \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 -\u0648\u0647\u064a \u0645\u0646 \u0623\u0641\u0635\u062d \u0627\u0644\u0639\u0631\u0628- \u0638\u0647\u0648\u0631\u064e \u0631\u0624\u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0630\u0627 \u0627\u0633\u062a\u064a\u0642\u0638 \u0628\u0647\u0627 \u0645\u0646 \u0643\u0645\u0627\u0644 \u0648\u0636\u0648\u062d\u0647\u0627 \u0628\u0638\u0647\u0648\u0631 \u0636\u0648\u0621 \u0627\u0644\u0635\u0628\u062d \u064a\u064e\u0646\u0641\u0644\u0642 \u0639\u0646\u0647 \u063a\u0628\u0634\u064f \u0627\u0644\u0638\u0644\u0627\u0645\u060c \u0648\u0647\u0648 \u062a\u0635\u0648\u064a\u0631 \u0628\u064a\u0627\u0646\u064a \u0644\u0627 \u062a\u0646\u0641\u0644\u0642 \u062f\u0646\u064a\u0627 \u0627\u0644\u0639\u0631\u0628 \u0641\u064a \u0630\u0631\u0649 \u0641\u0635\u0627\u062d\u062a\u0647\u0645 \u0639\u0646 \u0623\u0628\u0644\u063a \u0645\u0646\u0647."],t.s)
