B.aF9=s(["\u0628\u0639\u062f \u0623\u0646 \u062a\u064a\u0642\u064e\u0651\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646\u0647 \u0623\u0635\u0628\u062d \u0646\u0628\u064a\u064b\u0651\u0627 \u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644\u060c \u0648\u062c\u0627\u0621\u0647 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0644\u0644\u0645\u0631\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629\u060c \u0648\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0646\u0628\u064a\u0647 \ufdfa \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0645\u064f\u062f\u0651\u064e\u062b\u0651\u0650\u0631\u064f \u06dd \u0642\u064f\u0645 \u0641\u064e\u0623\u064e\u0646\u0630\u0650\u0631 \u06dd \u0648\u064e\u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0641\u064e\u0643\u064e\u0628\u0651\u0650\u0631 \u06dd \u0648\u064e\u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0643\u064e \u0641\u064e\u0637\u064e\u0647\u0651\u0650\u0631\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u062f\u062b\u0631.","\u0643\u0627\u0646\u062a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u062a\u0627\u0628\u0639\u0629 \u0625\u0634\u0639\u0627\u0631\u064b\u0627 \u0644\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0628\u0623\u0646 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0633\u0643\u064a\u0646\u0629 \u0648\u0627\u0644\u0647\u062f\u0648\u0621 \u0642\u062f \u0627\u0646\u0642\u0636\u062a\u060c \u0648\u0623\u0646 \u0623\u0645\u0627\u0645\u0647 \u0639\u0645\u0644\u0627\u064b \u0639\u0638\u064a\u0645\u064b\u0627 \u064a\u0633\u062a\u062f\u0639\u064a \u0627\u0644\u064a\u0642\u0638\u0629 \u0648\u0627\u0644\u062a\u0634\u0645\u064a\u0631\u061b \u0644\u064a\u0628\u062f\u0623 \u062d\u0645\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0646\u0627\u0633\u060c \u0645\u0633\u062a\u0623\u0646\u0633\u064b\u0627 \u0628\u0627\u0644\u0648\u062d\u064a\u060c \u0645\u0633\u062a\u0645\u062f\u064b\u0627 \u0645\u0646\u0647 \u0627\u0644\u0642\u0648\u0629 \u0639\u0644\u0649 \u062a\u062d\u0645\u0644 \u0623\u0639\u0628\u0627\u0626\u0647\u0627\u060c \u0641\u062c\u0627\u0621 \u0627\u0644\u0646\u062f\u0627\u0621 \u0627\u0644\u0645\u062a\u0644\u0637\u0641 \ufd3f\u064a\u064e\u0627 \u0623\u064e\u064a\u064f\u0651\u0647\u064e\u0627 \u0627\u0644\u0645\u064f\u062f\u064e\u0651\u062b\u0650\u0651\u0631\u064f\ufd3e\u060c \u0623\u0639\u0642\u0628\u0647 \u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u062c\u0627\u0632\u0645 \ufd3f\u0642\u064f\u0645\ufd3e \u0628\u0639\u0632\u064a\u0645\u0629 \u0646\u0627\u0647\u0636\u0629 \u062a\u062a\u062c\u0647 \u0625\u0644\u0649 \u062a\u062d\u0642\u064a\u0642 \u0648\u0627\u062c\u0628 \u0627\u0644\u062a\u0628\u0644\u064a\u063a\u060c \u0648\u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \u0623\u0646 \u0647\u0630\u0647 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0627\u0644\u0635\u0628\u0631 \u0648\u0627\u0644\u062c\u0647\u0627\u062f \u0627\u0644\u0645\u0631\u064a\u0631.","\u062b\u0645 \u062c\u0627\u0621 \u0627\u0644\u0623\u0645\u0631 \ufd3f\u0648\u064e\u0631\u064e\u0628\u064e\u0651\u0643\u064e \u0641\u064e\u0643\u064e\u0628\u0650\u0651\u0631\ufd3e \u0644\u064a\u0632\u064a\u062f\u0647 \u062b\u0628\u0627\u062a\u064b\u0627 \u0648\u0642\u0648\u0629\u060c \u0648\u0645\u0639\u0646\u0627\u0647: \u0623\u0644\u0651\u0627 \u064a\u064f\u0639\u0638\u0650\u0651\u0645 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u062e\u0644\u0642 \u0648\u0644\u0627 \u064a\u062e\u0634\u0649 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646\u0647\u0645\u060c \ufd3f\u0648\u064e\u062b\u0650\u064a\u064e\u0627\u0628\u064e\u0643\u064e \u0641\u064e\u0637\u064e\u0647\u0650\u0651\u0631\ufd3e \u0641\u0643\u0623\u0646\u0647 \u0642\u064a\u0644 \u0644\u0647 \ufdfa: \u0641\u0623\u0646\u062a \u0639\u0644\u0649 \u0637\u064f\u0647\u0631\u0643 \u0648\u062a\u0637\u0647\u0631\u0643 \u0628\u0641\u0637\u0631\u062a\u0643 \u0641\u064a \u0643\u0645\u0627\u0644 \u0625\u0646\u0633\u0627\u0646\u064a\u062a\u0643 \u0628\u0645\u0627 \u0637\u064e\u0628\u064e\u0639\u064e\u0643 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0623\u0643\u0631\u0645 \u0645\u0643\u0627\u0631\u0645 \u0627\u0644\u0623\u062e\u0644\u0627\u0642\u060c \u0648\u0628\u0645\u0627 \u062d\u064e\u0628\u064e\u0627\u0643 \u0628\u0647 \u0645\u0646 \u0646\u0628\u0648\u062a\u0647 \u0644\u064a\u0639\u062f\u064e\u0651\u0643 \u0628\u0647\u0627 \u0644\u064a\u0648\u0645\u0643 \u0647\u0630\u0627\u060c \u0623\u064e\u062d\u0648\u062c\u064f \u0625\u0644\u0649 \u0623\u0646 \u062a\u0632\u062f\u0627\u062f \u0641\u064a \u062a\u0637\u0647\u0631\u0643 \u0627\u0644\u0646\u0641\u0633\u064a \u0641\u062a\u0632\u062f\u0627\u062f \u0645\u0646 \u0627\u0644\u0645\u0643\u0627\u0631\u0645 \u0641\u064a \u062d\u064a\u0627\u062a\u0643 \u0645\u0639 \u0627\u0644\u0646\u0627\u0633 \u0648\u0627\u0644\u0623\u0634\u064a\u0627\u0621\u060c \u0641\u0623\u0646\u062a \u0627\u0644\u064a\u0648\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646\u060c \u0648\u0643\u0645\u0627\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0641\u064a \u0643\u0645\u0627\u0644 \u0627\u0644\u062e\u064f\u0644\u064f\u0642 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0635\u0628\u0631\u064b\u0627 \u0648\u062d\u0644\u0645\u064b\u0627 \u0648\u0639\u0641\u0648\u064b\u0627 \u0648\u0625\u062d\u0633\u0627\u0646\u064b\u0627\u060c \u0648\u062f\u064f\u0624\u064f\u0648\u0628\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u062c\u062f \u0641\u064a \u062a\u0628\u0644\u064a\u063a \u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0644\u0627 \u064a\u062b\u0646\u064a\u0643 \u0625\u064a\u0630\u0627\u0621 \u0648\u0644\u0627 \u064a\u064f\u0642\u0639\u062f\u0643 \u0639\u0646 \u0627\u0644\u0645\u0636\u064a \u0625\u0644\u0649 \u063a\u0627\u064a\u062a\u0643 \u0641\u0627\u062f\u062d\u064f \u0627\u0644\u0628\u0644\u0627\u0621\u060c \u0648\u0641\u064a \u0642\u0648\u0644\u0647: \ufd3f\u0648\u064e\u0627\u0644\u0631\u064f\u0651\u062c\u0632\u064e \u0641\u064e\u0627\u0647\u062c\u064f\u0631\ufd3e \u0643\u0623\u0646\u0647 \u0642\u064a\u0644 \u0644\u0647 \ufdfa: \u0644\u064a\u0643\u0646 \u0642\u0635\u062f\u0643 \u0648\u0646\u064a\u062a\u0643 \u0641\u064a \u062a\u0631\u0643\u0643 \u0645\u0627 \u062a\u0631\u0643\u062a\u064e \u0641\u0637\u0631\u0629\u064b \u0648\u0637\u0628\u0639\u064b\u0627 \u0647\u062c\u0631\u064e\u0647 \u062a\u0643\u0644\u064a\u0641\u064b\u0627 \u0648\u062a\u0639\u0628\u062f\u064b\u0627 \u0644\u062a\u0643\u0648\u0646 \u0642\u062f\u0648\u0629 \u0623\u0645\u062a\u0643 \u0648\u0639\u0646\u0648\u0627\u0646\u064e \u062a\u0637\u0647\u0631\u0647\u0627 \u0628\u0647\u062f\u0627\u064a\u0629 \u0631\u0633\u0627\u0644\u062a\u0643."],t.s)
