B.aQH=s(["\u0628\u0639\u062f \u0646\u0632\u0648\u0644 \u0622\u064a\u0627\u062a \u0627\u0644\u0645\u062f\u062b\u0631 \u0642\u0627\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u062f\u0639\u0648 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0633\u0631\u064b\u0651\u0627\u060c \u0648\u0643\u0627\u0646 \u0637\u0628\u064a\u0639\u064a\u064b\u0627 \u0623\u0646 \u064a\u0628\u062f\u0623 \u0628\u0623\u0647\u0644 \u0628\u064a\u062a\u0647 \u0648\u0623\u0635\u062f\u0642\u0627\u0626\u0647 \u0648\u0623\u0642\u0631\u0628 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u064a\u0647.","\u0643\u0627\u0646\u062a \u0623\u0648\u0644 \u0645\u0646 \u0622\u0645\u0646 \u0628\u0627\u0644\u0646\u0628\u064a \ufdfa \u0645\u0646 \u0627\u0644\u0646\u0633\u0627\u0621\u060c \u0628\u0644 \u0623\u0648\u0644 \u0645\u0646 \u0622\u0645\u0646 \u0628\u0647 \u0639\u0644\u0649 \u0627\u0644\u0625\u0637\u0644\u0627\u0642\u060c \u0641\u0643\u0627\u0646\u062a \u0623\u0648\u0644 \u0645\u0646 \u0627\u0633\u062a\u0645\u0639 \u0625\u0644\u0649 \u0627\u0644\u0648\u062d\u064a \u0627\u0644\u0625\u0644\u0647\u064a \u0645\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0623\u0648\u0644 \u0645\u0646 \u062a\u0644\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0639\u062f \u0623\u0646 \u0633\u0645\u0639\u062a\u0647 \u0645\u0646 \u0635\u0648\u062a\u0647 \ufdfa\u060c \u0648\u0623\u0648\u0644 \u0645\u0646 \u062a\u0639\u0644\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0639\u0646\u0647\u060c \u0641\u0628\u064a\u062a\u0647\u0627 \u0647\u0648 \u0623\u0648\u0644 \u0645\u0643\u0627\u0646 \u062a\u064f\u0644\u0650\u064a\u064e \u0641\u064a\u0647 \u0623\u0648\u0644 \u0648\u062d\u064a \u0646\u0632\u0644 \u0628\u0647 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u0649 \u0642\u0644\u0628 \u0627\u0644\u0645\u0635\u0637\u0641\u0649 \u0627\u0644\u0643\u0631\u064a\u0645 \ufdfa \u0628\u0639\u062f \u063a\u0627\u0631 \u062d\u0631\u0627\u0621.","\u0643\u0627\u0646 \u0623\u0648\u0644 \u0634\u064a\u0621 \u0641\u0631\u0636\u0647 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0634\u0631\u0627\u0626\u0639 \u0628\u0639\u062f \u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0625\u0642\u0627\u0645\u0629\u064e \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0642\u062f \u062c\u0627\u0621 \u0641\u064a \u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u062d\u062f\u064a\u062b \u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0632\u0648\u062c\u062a\u064e\u0647 \u062e\u062f\u064a\u062c\u0629\u064e \u0627\u0644\u0648\u0636\u0648\u0621 \u0648\u0627\u0644\u0635\u0644\u0627\u0629 \u062d\u064a\u0646 \u0627\u0641\u062a\u064f\u0631\u0650\u0636\u064e\u062a \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u061b \u0623\u062a\u0627\u0647 \u062c\u0628\u0631\u064a\u0644 \u0648\u0647\u0648 \u0628\u0623\u0639\u0644\u0649 \u0645\u0643\u0629 \u0641\u0647\u064e\u0645\u064e\u0632\u064e \u0644\u0647 \u0628\u0639\u0642\u0628\u0647 \u0641\u064a \u0646\u0627\u062d\u064a\u0629 \u0627\u0644\u0648\u0627\u062f\u064a \u0641\u0627\u0646\u0641\u062c\u0631\u062a \u0645\u0646\u0647 \u0639\u064a\u0646\u060c \u0641\u062a\u0648\u0636\u0623 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0648\u0627\u0644\u0631\u0633\u0648\u0644 \u064a\u0646\u0638\u0631 \u0644\u064a\u0631\u064a\u0647 \u0643\u064a\u0641 \u0627\u0644\u0637\u0647\u0648\u0631 \u0644\u0644\u0635\u0644\u0627\u0629\u060c \u062b\u0645 \u062a\u0648\u0636\u0623 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0643\u0645\u0627 \u0631\u0623\u0649 \u062c\u0628\u0631\u064a\u0644 \u062a\u0648\u0636\u0623\u060c \u062b\u0645 \u0642\u0627\u0645 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0641\u0635\u0644\u0649 \u0628\u0647 \u0648\u0635\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0635\u0644\u0627\u062a\u0647\u060c \u062b\u0645 \u0627\u0646\u0635\u0631\u0641 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u062c\u0627\u0621 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u062e\u062f\u064a\u062c\u0629\u064e \u0641\u062a\u0648\u0636\u0623 \u0644\u0647\u0627 \u064a\u0631\u064a\u0647\u0627 \u0643\u064a\u0641 \u0627\u0644\u0637\u0647\u0648\u0631 \u0644\u0644\u0635\u0644\u0627\u0629 \u0643\u0645\u0627 \u0623\u0631\u0627\u0647 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u062a\u0648\u0636\u0623\u062a \u0643\u0645\u0627 \u062a\u0648\u0636\u0623 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u062b\u0645 \u0635\u0644\u0649 \u0628\u0647\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0643\u0645\u0627 \u0635\u0644\u0649 \u0628\u0647 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645."],t.s)
