B.aQR=s(["\u0628\u0639\u062f \u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0633\u064a\u062f\u0629 \u062e\u062f\u064a\u062c\u0629 \u062f\u062e\u0644 \u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0643\u0627\u0646 \u0623\u0648\u0644 \u0645\u0646 \u0622\u0645\u0646 \u0645\u0646 \u0627\u0644\u0635\u0628\u064a\u0627\u0646\u060c \u0648\u0643\u0627\u0646\u062a \u0633\u0646\u0651\u0647 \u0625\u0630 \u0630\u0627\u0643 \u0639\u0634\u0631 \u0633\u0646\u064a\u0646 \u0639\u0644\u0649 \u0623\u0631\u062c\u062d \u0627\u0644\u0623\u0642\u0648\u0627\u0644\u060c \u0648\u0647\u0648 \u0642\u0648\u0644 \u0627\u0644\u0637\u0628\u0631\u064a \u0648\u0627\u0628\u0646 \u0625\u0633\u062d\u0627\u0642\u060c \u0648\u0642\u062f \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0628\u0623\u0646 \u062c\u0639\u0644\u0647 \u064a\u062a\u0631\u0628\u0649 \u0641\u064a \u062d\u062c\u0631 \u0631\u0633\u0648\u0644\u0647 \ufdfa \u0642\u0628\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u062d\u064a\u062b \u0623\u062e\u0630\u0647 \u0645\u0646 \u0639\u0645\u0647 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0648\u0636\u0645\u0647 \u0625\u0644\u064a\u0647\u060c \u0648\u0643\u0627\u0646 \u0639\u0644\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u062b\u0627\u0644\u062b \u0645\u0646 \u0623\u0642\u0627\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0628\u0639\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0628\u0639\u062f \u062e\u062f\u064a\u062c\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627.","\u0648\u0642\u062f \u0630\u0643\u0631 \u0628\u0639\u0636 \u0623\u0647\u0644 \u0627\u0644\u0639\u0644\u0645 \u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0643\u0627\u0646 \u0625\u0630\u0627 \u062d\u0636\u0631\u062a \u0627\u0644\u0635\u0644\u0627\u0629 \u062e\u0631\u062c \u0625\u0644\u0649 \u0634\u0650\u0639\u0627\u0628 \u0645\u0643\u0629\u060c \u0648\u062e\u0631\u062c \u0645\u0639\u0647 \u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0645\u064f\u0633\u062a\u062e\u0641\u064a\u064b\u0627 \u0645\u0646 \u0623\u0628\u064a\u0647 \u0648\u0645\u0646 \u062c\u0645\u064a\u0639 \u0623\u0639\u0645\u0627\u0645\u0647 \u0648\u0633\u0627\u0626\u0631 \u0642\u0648\u0645\u0647\u060c \u0641\u064a\u0635\u0644\u064a\u0627\u0646 \u0627\u0644\u0635\u0644\u0648\u0627\u062a \u0641\u064a\u0647\u0627\u060c \u0641\u0625\u0630\u0627 \u0623\u0645\u0633\u064a\u0627 \u0631\u062c\u0639\u0627 \u0644\u064a\u0636\u0645\u0647\u0645\u0627 \u0630\u0644\u0643 \u0627\u0644\u0628\u064a\u062a \u0627\u0644\u0637\u0627\u0647\u0631 \u0627\u0644\u062a\u0642\u064a \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0627\u0644\u0645\u0641\u0639\u0645 \u0628\u0635\u062f\u0642 \u0627\u0644\u0648\u0641\u0627\u0621 \u0648\u0643\u0631\u0645 \u0627\u0644\u0645\u0646\u0628\u062a."],t.s)
