B.aw9=s(["\u0647\u0648 \u0623\u0648\u0644 \u0645\u0646 \u0622\u0645\u0646 \u0628\u0627\u0644\u062f\u0639\u0648\u0629 \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0644\u064a \u062d\u0650\u0628\u064f\u0651 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0645\u0648\u0644\u0627\u0647 \u0648\u0645\u064f\u062a\u064e\u0628\u0646\u064e\u0651\u0627\u0647: \u0632\u064a\u062f \u0628\u0646 \u062d\u0627\u0631\u062b\u0629 \u0627\u0644\u0643\u0644\u0628\u064a\u060c \u0627\u0644\u0630\u064a \u0622\u062b\u0631 \u0631\u0633\u0648\u0644\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0648\u0627\u0644\u062f\u0647 \u0648\u0623\u0647\u0644\u0647 \u0639\u0646\u062f\u0645\u0627 \u062c\u0627\u0624\u0648\u0627 \u0625\u0644\u0649 \u0645\u0643\u0629 \u0644\u0634\u0631\u0627\u0626\u0647 \u0645\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0641\u062a\u0631\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0623\u0645\u0631\u064e \u0644\u062d\u0627\u0631\u062b\u0629 \u0641\u0642\u0627\u0644 \u0632\u064a\u062f \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647: \u0645\u0627 \u0623\u0646\u0627 \u0628\u0627\u0644\u0630\u064a \u0623\u062e\u062a\u0627\u0631 \u0639\u0644\u064a\u0643 \u0623\u062d\u062f\u064b\u0627\u060c \u0648\u0623\u0646\u062a \u0645\u0646\u064a \u0628\u0645\u0646\u0632\u0644\u0629 \u0627\u0644\u0623\u0628 \u0648\u0627\u0644\u0639\u0645\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0648\u0627\u0644\u062f\u0647 \u0648\u0639\u0645\u0647: \u0648\u064a\u062d\u0643 \u062a\u062e\u062a\u0627\u0631 \u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062d\u0631\u064a\u0629 \u0648\u0639\u0644\u0649 \u0623\u0628\u064a\u0643 \u0648\u0639\u0645\u0643 \u0648\u0623\u0647\u0644 \u0628\u064a\u062a\u0643\u061f \u0642\u0627\u0644: \u0646\u0639\u0645\u060c \u0648\u0625\u0646\u064a \u0631\u0623\u064a\u062a \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0634\u064a\u0626\u064b\u0627 \u0645\u0627 \u0623\u0646\u0627 \u0628\u0627\u0644\u0630\u064a \u0623\u062e\u062a\u0627\u0631 \u0639\u0644\u064a\u0647 \u0623\u062d\u062f\u064b\u0627 \u0623\u0628\u062f\u064b\u0627.","\u0627\u0644\u0645\u0639\u0627\u0646\u064a: [\u0627\u0644\u0645\u0648\u0627\u0644\u064a: \u064a\u0637\u0644\u0642 \u0627\u0644\u0645\u0648\u0644\u0649 \u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u062f\u060c \u0648\u0639\u0644\u0649 \u0627\u0644\u0645\u0645\u0644\u0648\u0643 \u0627\u0644\u0630\u064a \u0623\u064f\u0639\u062a\u0650\u0642\u064e \u0648\u0647\u0648 \u0627\u0644\u0645\u0631\u0627\u062f \u0647\u0646\u0627]."],t.s)
