B.aD_=s(["\u062a\u062d\u0645\u0644 \u0642\u0635\u0629\u064f \u0625\u0633\u0644\u0627\u0645 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0639\u064e\u0628\u064e\u0633\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u062f\u0631\u0648\u0633\u0627\u064b \u0648\u0639\u0650\u0628\u0631\u0627\u064b \u0628\u0644\u064a\u063a\u0629\u060c \u0641\u0642\u062f \u0643\u0627\u0646 \u0642\u0628\u0644 \u0625\u0633\u0644\u0627\u0645\u0647 \u0645\u0646 \u0627\u0644\u062d\u064f\u0646\u0641\u0627\u0621 \u0627\u0644\u0645\u064f\u0646\u0643\u0650\u0631\u064a\u0646 \u0644\u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u060c \u062b\u0645 \u0643\u0627\u0646\u062a \u0627\u0644\u062d\u0631\u0648\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0645\u064a\u0629 \u0627\u0644\u0636\u0631\u0648\u0633 \u0627\u0644\u062a\u064a \u0634\u0646\u064e\u0651\u062a\u0647\u0627 \u0642\u0631\u064a\u0634 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0633\u0628\u0628\u0627\u064b \u0641\u064a \u062a\u062a\u0628\u064f\u0651\u0639\u0647 \u0623\u062e\u0628\u0627\u0631\u064e\u0647\u060c \u0648\u062d\u064a\u0646 \u0642\u062f\u0650\u0645 \u0645\u0643\u0629 \u062a\u0628\u064a\u064e\u0651\u0646 \u0644\u0647 \u0645\u062f\u0649 \u062c\u064f\u0631\u0623\u0629 \u0642\u0631\u064a\u0634 \u0648\u0634\u0650\u062f\u064e\u0651\u062a\u0647\u0627 \u0639\u0644\u064a\u0647\u060c \u0648\u0647\u0648 \u0645\u0627 \u0639\u0628\u064e\u0651\u0631 \u0639\u0646\u0647 \u0628\u0642\u0648\u0644\u0647: \u0641\u062a\u0644\u0637\u064e\u0651\u0641\u062a\u064f \u062d\u062a\u0649 \u062f\u062e\u0644\u062a\u064f \u0639\u0644\u064a\u0647\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u062f\u0631\u0633\u064c \u0641\u064a \u0623\u062f\u0628 \u0627\u0644\u062f\u062e\u0648\u0644 \u0639\u0644\u0649 \u0623\u0647\u0644 \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u0645\u0646\u0632\u0644\u0629.","\u0648\u0628\u0633\u0624\u0627\u0644\u0647 \ufdfa \u0639\u0646 \u0641\u062d\u0648\u0649 \u062f\u0639\u0648\u062a\u0647\u060c \u0627\u062a\u0636\u062d \u0623\u0646 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0645\u062d\u0645\u062f\u064a\u0629 \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0631\u0643\u064a\u0632\u062a\u064a\u0646 \u0644\u0627 \u062a\u0646\u0641\u0635\u0644\u0627\u0646: \u062d\u0642 \u0627\u0644\u0644\u0647\u060c \u0648\u062d\u0642 \u0627\u0644\u062e\u0644\u0642\u060c \u062d\u064a\u0646 \u0642\u0627\u0644: \xab\u0623\u0631\u0633\u0644\u0646\u064a \u0628\u0635\u0644\u0629 \u0627\u0644\u0623\u0631\u062d\u0627\u0645\u060c \u0648\u0643\u0633\u0631 \u0627\u0644\u0623\u0648\u062b\u0627\u0646\xbb\u060c \u0641\u0641\u064a \u0647\u0630\u0627 \u062f\u0644\u0627\u0644\u0629\u064c \u0639\u0644\u0649 \u0623\u0646 \u0635\u0644\u0629 \u0627\u0644\u0623\u0631\u062d\u0627\u0645 \u0643\u0627\u0646\u062a \u0623\u0644\u0635\u0642\u064e \u0645\u0627 \u064a\u0643\u0648\u0646 \u0628\u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0629 \u0645\u0642\u062a\u0631\u0646\u0629\u064b \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f\u060c \u0643\u0645\u0627 \u0641\u064a\u0647 \u0647\u062c\u0648\u0645\u064c \u0635\u0631\u064a\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0645\u0639 \u0623\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u0623\u0642\u062f\u0633\u064e \u0634\u064a\u0621 \u0639\u0646\u062f \u0627\u0644\u0639\u0631\u0628\u060c \u0645\u0645\u0627 \u064a\u0624\u0643\u062f \u0623\u0647\u0645\u064a\u0629 \u0625\u0632\u0627\u0644\u0629 \u0645\u0639\u0627\u0644\u0645 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u060c \u0623\u0646 \u062f\u0639\u0648\u0629 \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0644\u0627 \u062a\u0633\u062a\u0642\u0631 \u0648\u0644\u0627 \u062a\u0646\u062a\u0634\u0631 \u0625\u0644\u0627 \u0628\u0632\u0648\u0627\u0644 \u0645\u0639\u0627\u0644\u0645 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629.","\u0648\u0641\u064a \u0627\u0647\u062a\u0645\u0627\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0627\u0644\u0645\u0628\u0643\u0631 \u0628\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0645\u0639 \u0639\u062f\u0645 \u0642\u062f\u0631\u062a\u0647 \u0639\u0646 \u062a\u0646\u0641\u064a\u0630 \u0630\u0644\u0643 \u0622\u0646\u0630\u0627\u0643 \u062f\u0644\u0627\u0644\u0629\u064c \u0639\u0644\u0649 \u0623\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u062f\u064a\u0646 \u0644\u0627 \u064a\u062c\u0648\u0632 \u062a\u0623\u062e\u064a\u0631 \u0628\u064a\u0627\u0646\u0647\u0627 \u0644\u0644\u0646\u0627\u0633 \u0628\u062d\u062c\u0629 \u0639\u062f\u0645 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0637\u0628\u064a\u0642\u0647\u0627\u060c \u0641\u0627\u0644\u062f\u0627\u0639\u064a\u0629 \u0627\u0644\u0630\u064a \u064a\u064f\u0628\u064a\u0650\u0651\u0646 \u0644\u0644\u0646\u0627\u0633 \u0645\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u062a\u0637\u0628\u064a\u0642\u0647 \u0628\u0633\u0647\u0648\u0644\u0629 \u0648\u064a\u064f\u062d\u062c\u0650\u0645 \u0639\u0645\u0627 \u064a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0645\u0648\u0627\u062c\u0647\u0629 \u0648\u062c\u0647\u0627\u062f\u060c \u062a\u0643\u0648\u0646 \u062f\u0639\u0648\u062a\u064f\u0647 \u0646\u0627\u0642\u0635\u0629\u060c \u0648\u0644\u0645 \u064a\u0642\u062a\u062f\u0650 \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0630\u064a \u0635\u062f\u064e\u0639 \u0628\u0627\u0644\u062d\u0642 \u0648\u0647\u0648 \u0641\u064a \u0642\u0650\u0644\u064e\u0651\u0629 \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0627\u0644\u0633\u064a\u0627\u062f\u0629 \u0641\u064a \u0628\u0644\u062f\u0647 \u0644\u0623\u0639\u062f\u0627\u0626\u0647.","\u0648\u0628\u0627\u0644\u0645\u0648\u0627\u0632\u0627\u0629 \u0645\u0639 \u0647\u0630\u0627 \u0627\u0644\u0635\u062f\u0639\u060c \u0638\u0647\u0631 \u062d\u0631\u0635\u064f\u0647 \u0627\u0644\u0634\u062f\u064a\u062f \u0639\u0644\u0649 \u0623\u0645\u0627\u0646 \u0635\u062d\u0627\u0628\u062a\u0647 \u0648\u0625\u0628\u0639\u0627\u062f\u0647\u0645 \u0639\u0646 \u0645\u0648\u0627\u0637\u0646 \u0627\u0644\u062e\u0637\u0631\u060c \u062d\u064a\u0646 \u0642\u0627\u0644 \u0644\u0639\u0645\u0631\u0648: \xab\u0625\u0646\u0643 \u0644\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u064a\u0648\u0645\u064e\u0643 \u0647\u0630\u0627\xbb\u060c \u0643\u0645\u0627 \u062a\u062c\u0644\u064e\u0651\u0649 \u0643\u0631\u0645\u064f \u062e\u064f\u0644\u064f\u0642\u0647 \u0648\u062a\u0630\u0643\u064f\u0651\u0631\u064f\u0647 \u0644\u0623\u062d\u0648\u0627\u0644 \u0623\u0635\u062d\u0627\u0628\u0647 \u062d\u064a\u0646 \u0627\u0644\u062a\u0642\u064a\u0627 \u0641\u0642\u0627\u0644 \u0644\u0647: \xab\u0623\u0646\u062a \u0627\u0644\u0630\u064a \u0644\u0642\u064a\u062a\u064e\u0646\u064a \u0628\u0645\u0643\u0629\xbb.","\u0648\u0645\u0646 \u0641\u0642\u0647 \u0627\u0644\u0642\u064a\u0627\u062f\u0629 \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062f\u0639\u0648\u064a\u0629\u060c \u0644\u0645 \u064a\u0643\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u064a\u064f\u0639\u0637\u064a \u0643\u0644\u064e\u0651 \u0645\u0646 \u0623\u0633\u0644\u0645 \u0642\u0627\u0626\u0645\u0629\u064b \u0628\u0623\u0633\u0645\u0627\u0621 \u0623\u062a\u0628\u0627\u0639\u0647\u060c \u0625\u0630 \u0644\u064a\u0633 \u0644\u0644\u0633\u0627\u0626\u0644 \u0641\u064a \u0630\u0644\u0643 \u0645\u0635\u0644\u062d\u0629\u064c \u0648\u0644\u0627 \u064a\u062a\u0639\u0644\u0642 \u0628\u0647 \u0628\u0644\u0627\u063a\u060c \u0648\u0644\u0630\u0627 \u0644\u0645\u0627 \u0633\u0623\u0644\u0647 \u0639\u0645\u0631\u0648 \u0639\u0645\u064e\u0651\u0646 \u062a\u0628\u0650\u0639\u0647 \u0642\u0627\u0644: \xab\u062d\u0631\u064c\u0651 \u0648\u0639\u0628\u062f\xbb\u060c \u0648\u0647\u064a \u062a\u0648\u0631\u064a\u0629\u064c \u0643\u0645\u0627 \u0630\u0643\u0631 \u0627\u0628\u0646 \u0643\u062b\u064a\u0631\u060c \u0625\u0630 \u0641\u0647\u0650\u0645 \u0639\u0645\u0631\u0648 \u0623\u0646\u0647 \u0627\u0633\u0645\u064f \u0639\u064e\u064a\u0646 \u0648\u0647\u0648 \u0627\u0633\u0645\u064f \u062c\u0646\u0633.","\u0648\u062a\u062a\u062c\u0644\u0649 \u062d\u0643\u0645\u0629 \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0646\u0628\u0648\u064a \u0641\u064a \u0642\u0648\u0644\u0647: \xab\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0623\u0647\u0644\u0643\u060c \u0641\u0625\u0630\u0627 \u0633\u0645\u0639\u062a\u064e \u0628\u064a \u0642\u062f \u0638\u0647\u0631\u062a\u064f \u0641\u0623\u062a\u0650\u0646\u064a\xbb\u060c \u0648\u0647\u0648 \u062f\u0631\u0633\u064c \u0639\u0645\u064a\u0642 \u064a\u0624\u0643\u062f \u0623\u0646 \u062a\u062c\u0645\u064a\u0639 \u0645\u0646 \u0622\u0645\u0646 \u0628\u0647 \u0641\u064a \u0645\u0648\u0627\u0637\u0646 \u0627\u0644\u0645\u062d\u0646\u0629 \u0648\u0627\u0644\u0625\u064a\u0630\u0627\u0621 \u0644\u064a\u0633 \u0647\u0648 \u0627\u0644\u0623\u0635\u0644\u060c \u0641\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0645\u064e\u0631 \u0628\u0627\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u0649 \u0627\u0644\u0623\u0642\u0648\u0627\u0645\u060c \u0648\u0623\u0645\u064e\u0631 \u0643\u0630\u0644\u0643 \u0628\u0627\u0644\u0647\u062c\u0631\u062a\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062d\u0628\u0634\u0629 \u062a\u062e\u0641\u064a\u0641\u0627\u064b \u0639\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0625\u0628\u0639\u0627\u062f\u0627\u064b \u0644\u0647\u0645 \u0639\u0646 \u0645\u0648\u0627\u0637\u0646 \u0627\u0644\u062e\u0637\u0631\u060c \u0648\u0633\u062a\u0631\u0627\u064b \u0644\u0642\u0648\u064e\u0651\u062a\u0647\u0645\u060c \u0648\u0625\u0639\u0637\u0627\u0621\u064b \u0644\u0644\u0642\u0627\u0626\u062f \u0641\u0631\u0635\u0629\u064b \u0644\u0627 \u064a\u064f\u0634\u063a\u064e\u0644 \u0639\u0646\u0647\u0627\u060c \u0641\u0636\u0644\u0627\u064b \u0639\u0646 \u0636\u0645\u0627\u0646 \u0627\u0644\u0633\u0631\u064a\u0629 \u0648\u0625\u0641\u0627\u062f\u0629 \u0627\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0645\u064f\u0631\u0633\u064e\u0644 \u0625\u0644\u064a\u0647 \u0648\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644 \u0648\u062a\u062c\u0646\u064f\u0651\u0628 \u0627\u0644\u0627\u0633\u062a\u0626\u0635\u0627\u0644.","\u0648\u0639\u0644\u0649 \u0646\u0633\u0642 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0639\u0628\u0633\u0629\u060c \u0643\u0627\u0646 \u0627\u0644\u0637\u0641\u064a\u0644 \u0628\u0646 \u0639\u0645\u0631\u0648 \u0627\u0644\u062f\u0648\u0633\u064a \u0645\u0645\u0646 \u0623\u0633\u0644\u0645 \u0628\u0633\u0628\u0628 \u0627\u0644\u062d\u0631\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0645\u064a\u0629 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0642\u062f \u062c\u0627\u0621\u062a \u0642\u0635\u062a\u064f\u0647 \u0645\u064f\u0641\u0635\u064e\u0651\u0644\u0629 \u0641\u064a \u0643\u062a\u0628 \u0627\u0644\u0633\u064a\u0631\u0629\u060c \u0648\u064a\u0631\u0649 \u0627\u0644\u062f\u0643\u062a\u0648\u0631 \u0623\u0643\u0631\u0645 \u0636\u064a\u0627\u0621 \u0627\u0644\u0639\u064f\u0645\u0631\u064a \u0623\u0646\u0647 \u0644\u0645 \u064a\u062b\u0628\u062a \u0645\u0646\u0647\u0627 \u0625\u0644\u0627 \u0623\u0646\u0647 \u062f\u0639\u0627 \u0631\u0633\u0648\u0644\u064e \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0644\u0627\u0644\u062a\u062c\u0627\u0621 \u0625\u0644\u0649 \u062d\u0635\u0646 \u062f\u0648\u0633 \u0627\u0644\u0645\u0646\u064a\u0639 \u0641\u0623\u0628\u0649\u060c \u0643\u0645\u0627 \u0623\u0634\u0627\u0631\u062a \u0631\u0648\u0627\u064a\u0629\u064c \u0635\u062d\u064a\u062d\u0629 \u0625\u0644\u0649 \u0623\u0646 \u0627\u0644\u0637\u0641\u064a\u0644 \u062f\u0639\u0627 \u0642\u0648\u0645\u064e\u0647 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0644\u0642\u0650\u064a \u0645\u0646\u0647\u0645 \u0635\u064f\u062f\u0648\u062f\u0627\u064b \u062d\u062a\u0649 \u0637\u0644\u0628 \u0645\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0646 \u064a\u062f\u0639\u0648 \u0639\u0644\u064a\u0647\u0645\u060c \u0644\u0643\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062f\u0639\u0627 \u0644\u0647\u0645 \u0628\u0627\u0644\u0647\u062f\u0627\u064a\u0629\u060c \u0648\u0643\u0627\u0646 \u0622\u0646\u0626\u0630\u064d \u0628\u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0627\u0644\u0645\u0646\u0648\u0631\u0629."],t.s)
