B.aB1=s(["\u0643\u0645\u0627 \u0628\u0631\u0632 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u062d\u0633\u064f\u0651 \u0627\u0644\u0623\u0645\u0646\u064a \u0644\u0623\u0645 \u062c\u0645\u064a\u0644 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0639\u0628\u0631 \u062a\u0635\u0631\u0641\u0627\u062a \u0630\u0643\u064a\u0629 \u0645\u062a\u0639\u062f\u062f\u0629\u060c \u0643\u0627\u0646 \u0623\u0648\u0644\u0647\u0627 \u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0648\u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0625\u0646\u0643\u0627\u0631\u060c \u0641\u0639\u0646\u062f\u0645\u0627 \u0633\u0623\u0644\u062a\u0647\u0627 \u0623\u0645 \u0627\u0644\u062e\u064a\u0631 \u0639\u0646 \u0645\u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0646\u0643\u0631\u064e\u062a \u0645\u0639\u0631\u0641\u062a\u0647\u0627 \u0628\u0623\u0628\u064a \u0628\u0643\u0631 \u0648\u0645\u062d\u0645\u062f \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u0648 \u062a\u0635\u0631\u0641 \u062d\u0630\u0631\u064c \u0633\u0644\u064a\u0645\u060c \u0643\u0648\u0646 \u0623\u0645 \u0627\u0644\u062e\u064a\u0631 \u0644\u0645 \u062a\u0643\u0646 \u0645\u0633\u0644\u0645\u0629 \u0648\u0642\u062a\u0626\u0630\u064d\u060c \u0628\u064a\u0646\u0645\u0627 \u0643\u0627\u0646\u062a \u0623\u0645 \u062c\u0645\u064a\u0644 \u062a\u064f\u062e\u0641\u064a \u0625\u0633\u0644\u0627\u0645\u0647\u0627 \u0645\u062e\u0627\u0641\u0629 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0623\u0645 \u0627\u0644\u062e\u064a\u0631 \u0639\u064a\u0646\u0627\u064b \u0644\u0642\u0631\u064a\u0634.","\u062b\u0645 \u0623\u062a\u0628\u0639\u062a \u0630\u0644\u0643 \u0628\u0623\u0646 \u0623\u0631\u0627\u062f\u062a \u0625\u064a\u0635\u0627\u0644 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u0628\u0646\u0641\u0633\u0647\u0627 \u0625\u0644\u0649 \u0623\u0628\u064a \u0628\u0643\u0631 \u062f\u0648\u0646 \u0623\u0646 \u062a\u064f\u0638\u0647\u0631 \u0630\u0644\u0643 \u0644\u0623\u0645 \u0627\u0644\u062e\u064a\u0631\u060c \u0625\u0645\u0639\u0627\u0646\u0627\u064b \u0641\u064a \u0627\u0644\u0633\u0631\u064a\u0629 \u0648\u0627\u0644\u0643\u062a\u0645\u0627\u0646\u060c \u0641\u0639\u0631\u0636\u062a \u0645\u0631\u0627\u0641\u0642\u062a\u0647\u0627 \u0628\u0637\u0631\u064a\u0642\u0629 \u062a\u0646\u0645\u0651 \u0639\u0646 \u0627\u0644\u0630\u0643\u0627\u0621 \u0648\u062d\u0633\u0646 \u0627\u0644\u062a\u0635\u0631\u0641\u060c \u0642\u0627\u0626\u0644\u0629\u064b: \xab\u0625\u0646 \u0643\u0646\u062a\u0650 \u062a\u062d\u0628\u064a\u0646 \u0623\u0646 \u0623\u0630\u0647\u0628 \u0645\u0639\u0643\u0650 \u0625\u0644\u0649 \u0627\u0628\u0646\u0643\u0650 \u0641\u0639\u0644\u062a\xbb\u060c \u0645\u0633\u062a\u062e\u062f\u0645\u0629\u064b \u0639\u0628\u0627\u0631\u0629 \xab\u0625\u0646 \u0643\u0646\u062a\u0650 \u062a\u062d\u0628\u064a\u0646\xbb \u0648\u0639\u0628\u0627\u0631\u0629 \xab\u0625\u0644\u0649 \u0627\u0628\u0646\u0643\u0650\xbb \u062f\u0648\u0646 \u062a\u0633\u0645\u064a\u0629 \u0623\u0628\u064a \u0628\u0643\u0631\u060c \u0643\u0644 \u0630\u0644\u0643 \u064a\u062d\u0631\u0651\u0643 \u0641\u064a \u0623\u0645 \u0627\u0644\u062e\u064a\u0631 \u0639\u0627\u0637\u0641\u0629 \u0627\u0644\u0623\u0645\u0648\u0645\u0629 \u0641\u0631\u0636\u062e\u062a \u0644\u0644\u0637\u0644\u0628 \u0648\u0623\u062c\u0627\u0628\u062a \u0628\u0640\xab\u0646\u0639\u0645\xbb\u060c \u0644\u062a\u0646\u062c\u062d \u0623\u0645 \u062c\u0645\u064a\u0644 \u0641\u064a \u0645\u0647\u0645\u062a\u0647\u0627.","\u0648\u0644\u0645 \u064a\u062a\u0648\u0642\u0641 \u0630\u0643\u0627\u0624\u0647\u0627 \u0639\u0646\u062f \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u060c \u0628\u0644 \u0627\u0633\u062a\u063a\u0644\u062a \u0627\u0644\u0645\u0648\u0642\u0641 \u0644\u0643\u0633\u0628 \u0639\u0637\u0641 \u0623\u0645 \u0623\u0628\u064a \u0628\u0643\u0631 \u0648\u062b\u0642\u062a\u0647\u0627 \u062a\u0633\u0647\u064a\u0644\u0627\u064b \u0644\u0645\u0647\u0645\u062a\u0647\u0627 \u0641\u064a \u0625\u064a\u0635\u0627\u0644 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629\u060c \u0641\u0645\u0627 \u0625\u0646 \u0631\u0623\u062a \u0627\u0644\u0635\u062f\u064a\u0642 \u0635\u0631\u064a\u0639\u0627\u064b \u062f\u064e\u0646\u0650\u0641\u0627\u064b \u062d\u062a\u0649 \u0623\u0639\u0644\u0646\u062a \u0628\u0627\u0644\u0635\u064a\u0627\u062d \u0648\u0633\u0628\u0651\u062a \u0627\u0644\u0641\u0627\u0639\u0644\u064a\u0646 \u0642\u0627\u0626\u0644\u0629: \xab\u0625\u0646 \u0642\u0648\u0645\u0627\u064b \u0646\u0627\u0644\u0648\u0627 \u0647\u0630\u0627 \u0645\u0646\u0643 \u0644\u0623\u0647\u0644 \u0641\u0633\u0642 \u0648\u0643\u0641\u0631\xbb\u060c \u0648\u0647\u0648 \u0645\u0648\u0642\u0641 \u064a\u0634\u0641\u064a \u0628\u0639\u0636 \u063a\u0644\u064a\u0644 \u0623\u0645 \u0627\u0644\u062e\u064a\u0631 \u0648\u064a\u062d\u0631\u0643 \u0641\u064a \u0646\u0641\u0633\u0647\u0627 \u0634\u064a\u0626\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u062d\u0628\u0629 \u0644\u0623\u0645 \u062c\u0645\u064a\u0644\u060c \u0641\u0643\u0633\u0628\u062a \u0628\u0630\u0644\u0643 \u0639\u0637\u0641\u064e\u0647\u0627 \u0648\u062b\u0642\u062a\u064e\u0647\u0627 \u0645\u0645\u0627 \u0633\u0647\u0651\u0644 \u0639\u0644\u064a\u0647\u0627 \u0625\u064a\u0635\u0627\u0644 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629.","\u0648\u0645\u0639 \u0647\u0630\u0627 \u0627\u0644\u062a\u0639\u0627\u0637\u0641\u060c \u0627\u0644\u062a\u0632\u0645\u062a \u0623\u0645 \u062c\u0645\u064a\u0644 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0637 \u0627\u0644\u062a\u0627\u0645 \u0642\u0628\u0644 \u0627\u0644\u0646\u0637\u0642 \u0628\u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u0627\u0644\u062e\u0637\u064a\u0631\u0629 \u0639\u0646 \u0645\u0643\u0627\u0646 \u0642\u0627\u0626\u062f \u0627\u0644\u062f\u0639\u0648\u0629 \u062a\u0641\u0627\u062f\u064a\u0627\u064b \u0644\u062a\u0633\u0631\u064a\u0628\u0647\u0627\u060c \u0641\u0644\u0645 \u062a\u0637\u0645\u0626\u0646 \u0644\u0623\u0645 \u0627\u0644\u062e\u064a\u0631 \u0644\u0623\u0646\u0647\u0627 \u0645\u0627 \u0632\u0627\u0644\u062a \u0645\u0634\u0631\u0643\u0629\u060c \u0648\u0638\u0647\u0631 \u0630\u0644\u0643 \u0641\u064a \u062a\u0631\u062f\u062f\u0647\u0627 \u0639\u0646\u062f\u0645\u0627 \u0633\u0623\u0644\u0647\u0627 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0639\u0646 \u062d\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0641\u0642\u0627\u0644\u062a \u0644\u0647: \xab\u0647\u0630\u0647 \u0623\u0645\u0643 \u062a\u0633\u0645\u0639\u061f\xbb\u060c \u0641\u0644\u0645\u0627 \u0637\u0645\u0623\u0646\u0647\u0627 \u0628\u0642\u0648\u0644\u0647: \xab\u0644\u0627 \u0634\u064a\u0621 \u0639\u0644\u064a\u0643 \u0645\u0646\u0647\u0627\xbb\u060c \u0623\u062e\u0628\u0631\u062a\u0647 \u0633\u0627\u0639\u062a\u0626\u0630\u064d \u0628\u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0633\u0627\u0644\u0645\u064c \u0635\u0627\u0644\u062d\u060c \u0648\u0632\u064a\u0627\u062f\u0629\u064b \u0641\u064a \u0627\u0644\u062d\u064a\u0637\u0629 \u0648\u0627\u0644\u062a\u0643\u062a\u0645 \u0644\u0645 \u062a\u064f\u062e\u0628\u0631\u0647 \u0628\u0645\u0643\u0627\u0646\u0647 \u0625\u0644\u0627 \u0628\u0639\u062f \u0623\u0646 \u0633\u0623\u0644\u0647\u0627: \xab\u0623\u064a\u0646 \u0647\u0648\u061f\xbb\u060c \u0641\u0623\u062c\u0627\u0628\u062a\u0647 \u0628\u0623\u0646\u0647 \u0641\u064a \u062f\u0627\u0631 \u0627\u0644\u0623\u0631\u0642\u0645.","\u0648\u062c\u0627\u0621 \u062a\u062e\u064a\u064f\u0651\u0631 \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u0644\u062a\u0646\u0641\u064a\u0630 \u0627\u0644\u0645\u0647\u0645\u0629 \u0643\u062d\u0644\u0642\u0629 \u0623\u062e\u064a\u0631\u0629 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0623\u0645\u0646\u064a\u060c \u0641\u062d\u064a\u0646 \u0637\u0644\u0628 \u0627\u0644\u0635\u062f\u064a\u0642 \u0627\u0644\u0630\u0647\u0627\u0628 \u0625\u0644\u0649 \u062f\u0627\u0631 \u0627\u0644\u0623\u0631\u0642\u0645 \u0644\u0645 \u062a\u0633\u062a\u062c\u0628 \u0644\u0647 \u0623\u0645 \u062c\u0645\u064a\u0644 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631\u060c \u0628\u0644 \u062a\u0631\u064a\u062b\u062a \u062d\u062a\u0649 \u0625\u0630\u0627 \u0647\u062f\u0623\u062a \u0627\u0644\u0631\u0650\u0651\u062c\u0644 \u0648\u0633\u0643\u0646 \u0627\u0644\u0646\u0627\u0633 \u062e\u0631\u062c\u062a \u0628\u0647 \u0648\u0645\u0639\u0647\u0627 \u0623\u0645\u0647 \u064a\u062a\u0643\u0626 \u0639\u0644\u064a\u0647\u0645\u0627\u060c \u0641\u064a \u0648\u0642\u062a \u062a\u0646\u0639\u062f\u0645 \u0641\u064a\u0647 \u0627\u0644\u0631\u0642\u0627\u0628\u0629 \u0645\u0646 \u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0644\u062a\u0646\u062a\u0647\u064a \u0627\u0644\u0645\u0647\u0645\u0629 \u0628\u0646\u062c\u0627\u062d \u062f\u0648\u0646 \u0623\u0646 \u064a\u0634\u0639\u0631 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0628\u062f\u062e\u0648\u0644\u0647\u0645 \u062c\u0645\u064a\u0639\u0627\u064b \u0625\u0644\u0649 \u062f\u0627\u0631 \u0627\u0644\u0623\u0631\u0642\u0645\u060c \u0648\u0647\u0630\u0627 \u064a\u0624\u0643\u062f \u0623\u0646 \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u062e\u062a\u0627\u0631 \u0643\u0627\u0646 \u0623\u0646\u0633\u0628 \u0627\u0644\u0623\u0648\u0642\u0627\u062a.","\u0648\u0639\u0642\u0628 \u0647\u0630\u0647 \u0627\u0644\u0645\u0650\u062d\u0646\u0629\u060c \u062a\u062c\u0644\u0649 \u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u0650\u0646\u062d\u0629 \u0627\u0644\u0631\u0628\u0627\u0646\u064a\u0629\u060c \u0625\u0630 \u0623\u0633\u0644\u0645\u064e\u062a \u0623\u0645 \u0627\u0644\u062e\u064a\u0631 \u0628\u0633\u0628\u0628 \u0631\u063a\u0628\u0629 \u0627\u0644\u0635\u062f\u064a\u0642 \u0641\u064a \u0625\u062f\u062e\u0627\u0644 \u0623\u0645\u0647 \u0625\u0644\u0649 \u062d\u0638\u064a\u0631\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0637\u0644\u0628\u0647 \u0645\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u062f\u0639\u0627\u0621 \u0644\u0647\u0627 \u0644\u0645\u0627 \u0631\u0623\u0649 \u0645\u0646 \u0628\u0631\u0651\u0647\u0627 \u0628\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u062d\u0631\u064a\u0635\u0627\u064b \u0639\u0644\u0649 \u0647\u062f\u0627\u064a\u0629 \u0627\u0644\u0646\u0627\u0633 \u0627\u0644\u0622\u062e\u0631\u064a\u0646 \u0641\u0643\u064a\u0641 \u0628\u0623\u0642\u0631\u0628\u0647\u0645 \u0625\u0644\u064a\u0647.","\u0648\u062a\u0624\u0643\u062f \u0647\u0630\u0647 \u0627\u0644\u0645\u0633\u064a\u0631\u0629 \u0628\u0645\u062c\u0645\u0644\u0647\u0627 \u0623\u0646 \u0623\u0628\u0627 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0643\u0627\u0646 \u0645\u0646 \u0623\u0643\u062b\u0631 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u062a\u0639\u0631\u0636\u0627\u064b \u0644\u0645\u062d\u0646\u0629 \u0627\u0644\u0623\u0630\u0649 \u0648\u0627\u0644\u0641\u062a\u0646\u0629 \u0628\u0639\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0630\u0644\u0643 \u0646\u0638\u0631\u0627\u064b \u0644\u0635\u062d\u0628\u062a\u0647 \u0627\u0644\u062e\u0627\u0635\u0629 \u0644\u0647 \u0648\u0627\u0644\u062a\u0635\u0627\u0642\u0647 \u0627\u0644\u062f\u0627\u0626\u0645 \u0628\u0647 \u0641\u064a \u0627\u0644\u0645\u0648\u0627\u0637\u0646 \u0627\u0644\u062a\u064a \u0643\u0627\u0646 \u064a\u062a\u0639\u0631\u0636 \u0641\u064a\u0647\u0627 \u0644\u0644\u0623\u0630\u0649 \u0645\u0646 \u0642\u0648\u0645\u0647\u060c \u0644\u064a\u062a\u0635\u062f\u0649 \u0627\u0644\u0635\u062f\u064a\u0642 \u0645\u062f\u0627\u0641\u0639\u0627\u064b \u0639\u0646\u0647 \u0641\u0627\u062f\u064a\u0627\u064b \u0625\u064a\u0627\u0647 \u0628\u0646\u0641\u0633\u0647 \u0641\u064a\u0635\u064a\u0628\u0647 \u0645\u0646 \u0623\u0630\u0649 \u0627\u0644\u0642\u0648\u0645 \u0648\u0633\u0641\u0647\u0647\u0645\u060c \u0639\u0644\u0649 \u0627\u0644\u0631\u063a\u0645 \u0645\u0646 \u0645\u0643\u0627\u0646\u062a\u0647 \u0627\u0644\u0639\u0627\u0644\u064a\u0629 \u0628\u0627\u0639\u062a\u0628\u0627\u0631\u0647 \u0645\u0646 \u0643\u0628\u0627\u0631 \u0631\u062c\u0627\u0644 \u0642\u0631\u064a\u0634 \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u064a\u0646 \u0628\u0627\u0644\u0639\u0642\u0644 \u0648\u0627\u0644\u0625\u062d\u0633\u0627\u0646."],t.s)
