B.aAi=s(["\u064a\u062a\u062c\u0644\u0649 \u0645\u0646 \u062f\u0631\u0648\u0633 \u0647\u062c\u0631\u0629 \u0627\u0644\u062d\u0628\u0634\u0629 \u0623\u0646 \u0627\u0644\u062c\u0647\u0644 \u0628\u0628\u0639\u0636 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0644\u0645\u0635\u0644\u062d\u0629 \u0631\u0627\u062c\u062d\u0629 \u0644\u0627 \u064a\u064e\u0636\u064f\u0631\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0633\u064a\u0627\u0642 \u064a\u064f\u0642\u0631\u0650\u0651\u0631 \u0627\u0628\u0646 \u062a\u064a\u0645\u064a\u0629 -\u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647- \u0645\u0633\u0623\u0644\u0629\u064e \u0627\u0644\u0639\u0630\u0631 \u0628\u0627\u0644\u062c\u0647\u0644 \u0642\u0627\u0626\u0644\u0627\u064b: \xab\u0648\u0644\u0645\u0627 \u0632\u064a\u062f \u0641\u064a \u0635\u0644\u0627\u0629 \u0627\u0644\u062d\u0636\u0631 \u062d\u064a\u0646 \u0647\u0627\u062c\u0631 \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0643\u0627\u0646 \u0645\u064e\u0646 \u0628\u0639\u064a\u062f\u0627\u064b \u0639\u0646\u0647 \u0645\u062b\u0644 \u0645\u0646 \u0643\u0627\u0646 \u0628\u0645\u0643\u0629\u060c \u0648\u0628\u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629 \u064a\u0635\u0644\u0648\u0646 \u0631\u0643\u0639\u062a\u064a\u0646\u060c \u0648\u0644\u0645 \u064a\u0623\u0645\u0631\u0647\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0635\u0644\u0627\u0629\xbb\u060c \u0648\u064a\u0624\u0643\u062f \u0647\u0630\u0627 \u0627\u0644\u062a\u0623\u0635\u064a\u0644\u064e \u0627\u0644\u0630\u0647\u0628\u064a \u0628\u0642\u0648\u0644\u0647: \xab\u0641\u0644\u0627 \u064a\u0623\u062b\u0645 \u0623\u062d\u062f \u0625\u0644\u0627 \u0628\u0639\u062f \u0627\u0644\u0639\u0644\u0645 \u0648\u0628\u0639\u062f \u0642\u064a\u0627\u0645 \u0627\u0644\u062d\u062c\u0629\u060c \u0648\u0642\u062f \u0643\u0627\u0646 \u0633\u0627\u062f\u0629 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0628\u0627\u0644\u062d\u0628\u0634\u0629 \u064a\u064e\u0646\u0632\u0650\u0644 \u0627\u0644\u0648\u0627\u062c\u0628 \u0648\u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u0644\u0627 \u064a\u0628\u0644\u063a\u0647\u0645 \u0625\u0644\u0627 \u0628\u0639\u062f \u0623\u0634\u0647\u0631 \u0641\u0647\u0645 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0623\u0645\u0648\u0631 \u0645\u0639\u0630\u0648\u0631\u0648\u0646 \u0628\u0627\u0644\u062c\u0647\u0644 \u062d\u062a\u0649 \u064a\u0628\u0644\u063a\u0647\u0645 \u0627\u0644\u0646\u0635\xbb.","\u0648\u0647\u062c\u0631\u0629 \u0627\u0644\u062d\u0628\u0634\u0629 \u062a\u064f\u0628\u0631\u0632 \u062f\u0631\u0633\u0627\u064b \u0628\u0644\u064a\u063a\u0627\u064b \u0641\u064a \u062a\u0641\u0627\u0636\u0644 \u0627\u0644\u062c\u0647\u0627\u062f \u062d\u0633\u0628 \u0627\u0644\u062d\u0627\u062c\u0629\u060c \u0641\u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0627\u0644\u0645\u0646\u0648\u0631\u0629 \u062c\u0647\u0627\u062f\u0627\u064b \u0645\u064a\u0651\u0632 \u0627\u0644\u0644\u0647 \u0623\u0635\u062d\u0627\u0628\u064e\u0647\u0627 \u0648\u062e\u0635\u0651\u0647\u0645 \u0628\u0627\u0644\u0630\u0643\u0631 \u0648\u0627\u0644\u0641\u0636\u064a\u0644\u0629\u060c \u0641\u0625\u0646 \u0623\u0635\u062d\u0627\u0628 \u0647\u062c\u0631\u0629 \u0627\u0644\u062d\u0628\u0634\u0629 \u0642\u062f \u0646\u0627\u0644\u0648\u0627 \u0647\u0630\u0627 \u0627\u0644\u0641\u0636\u0644 \u0627\u0644\u0639\u0638\u064a\u0645 \u0623\u064a\u0636\u0627\u064b \u0648\u0625\u0646 \u062a\u0623\u062e\u0651\u0631 \u0644\u062d\u0648\u0642\u064f\u0647\u0645 \u0628\u0627\u0644\u0646\u0628\u064a \ufdfa \u062d\u062a\u0649 \u0641\u062a\u062d \u062e\u064a\u0628\u0631\u060c \u0648\u0630\u0644\u0643 \u0644\u0634\u062f\u0629 \u0627\u0644\u062d\u0627\u062c\u0629 \u0648\u0627\u0644\u0645\u0635\u0644\u062d\u0629 \u0641\u064a \u0628\u0642\u0627\u0626\u0647\u0645 \u0628\u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629 \u0622\u0646\u0630\u0627\u0643\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u0645\u0642\u0627\u0645 \u0627\u0644\u0631\u0641\u064a\u0639 \u0647\u0648 \u0645\u0627 \u0623\u0643\u062f\u0647 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0633\u0641\u064a\u0646\u062a\u064a\u0646\u060c \u062d\u064a\u062b \u064a\u0631\u0648\u064a \u0623\u0628\u0648 \u0645\u0648\u0633\u0649 \u0627\u0644\u0623\u0634\u0639\u0631\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0626\u0644\u0627\u064b: \u0648\u062f\u062e\u0644\u062a\u0652 \u0623\u0633\u0645\u0627\u0621\u064f \u0628\u0646\u062a \u0639\u0645\u064a\u0633\u060c \u0648\u0647\u064a \u0645\u0645\u0646 \u0642\u064e\u062f\u0650\u0645 \u0645\u0639\u0646\u0627\u060c \u0639\u0644\u0649 \u062d\u0641\u0635\u0629 \u0632\u0648\u062c \u0627\u0644\u0646\u0628\u064a \ufdfa \u0632\u0627\u0626\u0631\u0629\u064b\u060c \u0648\u0642\u062f \u0643\u0627\u0646\u062a \u0647\u0627\u062c\u0631\u062a \u0625\u0644\u0649 \u0627\u0644\u0646\u062c\u0627\u0634\u064a \u0641\u064a\u0645\u0646 \u0647\u0627\u062c\u0631\u060c \u0641\u062f\u062e\u0644 \u0639\u0645\u0631 \u0639\u0644\u0649 \u062d\u0641\u0635\u0629 \u0648\u0623\u0633\u0645\u0627\u0621 \u0639\u0646\u062f\u0647\u0627\u060c \u0641\u0642\u0627\u0644 \u0639\u0645\u0631 \u062d\u064a\u0646 \u0631\u0623\u0649 \u0623\u0633\u0645\u0627\u0621: \u0645\u0646 \u0647\u0630\u0647\u061f \u0642\u0627\u0644\u062a: \u0623\u0633\u0645\u0627\u0621 \u0628\u0646\u062a \u0639\u0645\u064a\u0633\u060c \u0642\u0627\u0644: \u0627\u0644\u062d\u0628\u0634\u064a\u0629 \u0647\u0630\u0647\u060c \u0627\u0644\u0628\u062d\u0631\u064a\u0629 \u0647\u0630\u0647\u061f \u0642\u0627\u0644\u062a \u0623\u0633\u0645\u0627\u0621: \u0646\u0639\u0645\u060c \u0642\u0627\u0644: \u0633\u0628\u0642\u0646\u0627\u0643\u0645 \u0628\u0627\u0644\u0647\u062c\u0631\u0629 \u0641\u0646\u062d\u0646 \u0623\u062d\u0642 \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646\u0643\u0645\u060c \u0641\u063a\u0636\u0628\u062a \u0648\u0642\u0627\u0644\u062a: \u0643\u0644\u0627 \u0648\u0627\u0644\u0644\u0647 \u0643\u0646\u062a\u0645 \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u064f\u0637\u0639\u0645 \u062c\u0627\u0626\u0639\u064e\u0643\u0645\u060c \u0648\u064a\u064e\u0639\u0650\u0638 \u062c\u0627\u0647\u0644\u064e\u0643\u0645\u060c \u0648\u0643\u0646\u0627 \u0641\u064a \u062f\u0627\u0631 -\u0623\u0648 \u0641\u064a \u0623\u0631\u0636- \u0627\u0644\u0628\u064f\u0639\u062f\u0627\u0621 \u0627\u0644\u0628\u064f\u063a\u0636\u0627\u0621 \u0628\u0627\u0644\u062d\u0628\u0634\u0629\u060c \u0648\u0630\u0644\u0643 \u0641\u064a \u0627\u0644\u0644\u0647 \u0648\u0641\u064a \u0631\u0633\u0648\u0644\u0647 \ufdfa\u060c \u0648\u0623\u064a\u0645 \u0627\u0644\u0644\u0647 \u0644\u0627 \u0623\u0637\u0639\u0645 \u0637\u0639\u0627\u0645\u0627\u064b \u0648\u0644\u0627 \u0623\u0634\u0631\u0628 \u0634\u0631\u0627\u0628\u0627\u064b \u062d\u062a\u0649 \u0623\u0630\u0643\u0631 \u0645\u0627 \u0642\u0644\u062a\u064e \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0646\u062d\u0646 \u0643\u0646\u0627 \u0646\u064f\u0624\u0630\u064e\u0649 \u0648\u0646\u064f\u062e\u0627\u0641 \u0648\u0633\u0623\u0630\u0643\u0631 \u0630\u0644\u0643 \u0644\u0644\u0646\u0628\u064a \ufdfa \u0648\u0623\u0633\u0623\u0644\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u0623\u0643\u0630\u0628 \u0648\u0644\u0627 \u0623\u0632\u064a\u063a \u0648\u0644\u0627 \u0623\u0632\u064a\u062f \u0639\u0644\u064a\u0647\u060c \u0641\u0644\u0645\u0627 \u062c\u0627\u0621 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0642\u0627\u0644\u062a: \u064a\u0627 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0625\u0646 \u0639\u0645\u0631 \u0642\u0627\u0644 \u0643\u0630\u0627 \u0648\u0643\u0630\u0627\u060c \u0642\u0627\u0644: \xab\u0641\u0645\u0627 \u0642\u0644\u062a\u0650 \u0644\u0647\u061f\xbb \u0642\u0627\u0644\u062a: \u0642\u0644\u062a \u0644\u0647 \u0643\u0630\u0627 \u0648\u0643\u0630\u0627\u060c \u0642\u0627\u0644: \xab\u0644\u064a\u0633 \u0628\u0623\u062d\u0642 \u0628\u064a \u0645\u0646\u0643\u0645\u060c \u0648\u0644\u0647 \u0648\u0644\u0623\u0635\u062d\u0627\u0628\u0647 \u0647\u062c\u0631\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0644\u0643\u0645 \u0623\u0646\u062a\u0645 \u0623\u0647\u0644 \u0627\u0644\u0633\u0641\u064a\u0646\u0629 \u0647\u062c\u0631\u062a\u0627\u0646\xbb\u060c \u0642\u0627\u0644\u062a: \u0641\u0644\u0642\u062f \u0631\u0623\u064a\u062a \u0623\u0628\u0627 \u0645\u0648\u0633\u0649 \u0648\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0633\u0641\u064a\u0646\u0629 \u064a\u0623\u062a\u0648\u0646 \u0623\u0631\u0633\u0627\u0644\u0627\u064b \u064a\u0633\u0623\u0644\u0648\u0646\u064a \u0639\u0646 \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u060c \u0645\u0627 \u0645\u0646 \u0627\u0644\u062f\u0646\u064a\u0627 \u0634\u064a\u0621 \u0647\u0645 \u0628\u0647 \u0623\u0641\u0631\u062d\u064f \u0648\u0644\u0627 \u0623\u0639\u0638\u0645\u064f \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0645\u0627 \u0642\u0627\u0644 \u0644\u0647\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa."],t.s)
