B.aUO=s(["\u0627\u0645\u062a\u062f\u0627\u062f\u0627\u064b \u0644\u0628\u0631\u0643\u0627\u062a \u0647\u062c\u0631\u0629 \u0627\u0644\u062d\u0628\u0634\u0629\u060c \u064a\u0631\u062a\u0628\u0637 \u0632\u0648\u0627\u062c \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0628\u0623\u0645 \u062d\u0628\u064a\u0628\u0629 \u0628\u0647\u0630\u0647 \u0627\u0644\u0647\u062c\u0631\u0629 \u0627\u0631\u062a\u0628\u0627\u0637\u0627\u064b \u0648\u062b\u064a\u0642\u0627\u064b\u060c \u0648\u064a\u062d\u0645\u0644 \u0647\u0630\u0627 \u0627\u0644\u0632\u0648\u0627\u062c\u064f \u0645\u0646\u0647 \ufdfa \u0644\u0625\u062d\u062f\u0649 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0627\u062a \u0627\u0644\u062b\u0627\u0628\u062a\u0627\u062a \u0645\u0639\u0646\u0649\u064b \u0643\u0628\u064a\u0631\u0627\u064b \u0641\u064a \u0627\u0644\u062a\u0643\u0627\u0641\u0644 \u0648\u0627\u0644\u0645\u0648\u0627\u0633\u0627\u0629\u060c \u0648\u0642\u062f \u0643\u0627\u0646 \u0639\u0642\u062f \u0627\u0644\u0632\u0648\u0627\u062c \u0639\u0644\u0649 \u0623\u0645 \u062d\u0628\u064a\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0648\u0647\u064a \u0644\u0627 \u062a\u0632\u0627\u0644 \u0641\u064a \u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629\u060c \u0648\u062c\u0627\u0621 \u062a\u0623\u0643\u064a\u062f\u0647 \u0641\u064a \u0643\u062a\u0628 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0645\u0637\u0647\u0631\u0629\u061b \u0641\u0642\u062f \u0631\u0648\u0649 \u0623\u0628\u0648 \u062f\u0627\u0648\u062f \u0641\u064a \u0633\u0646\u0646\u0647 \u0628\u0633\u0646\u062f \u0635\u062d\u064a\u062d \u0639\u0646 \u0623\u0645 \u062d\u0628\u064a\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0623\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u062a\u062d\u062a \u0639\u0628\u064a\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u062c\u062d\u0634 \u0641\u0645\u0627\u062a \u0628\u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629\u060c \u0641\u0632\u0648\u0651\u062c\u0647\u0627 \u0627\u0644\u0646\u062c\u0627\u0634\u064a\u064f\u0651 \u0627\u0644\u0646\u0628\u064a\u064e\u0651 \ufdfa \u0648\u0623\u0645\u0647\u0631\u0647\u0627 \u0639\u0646\u0647 \u0623\u0631\u0628\u0639\u0629 \u0622\u0644\u0627\u0641\u060c \u0648\u0628\u0639\u062b \u0628\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0645\u0639 \u0634\u0631\u062d\u0628\u064a\u0644 \u0628\u0646 \u062d\u0633\u0646\u0629.","\u0648\u064a\u0633\u062a\u0646\u062a\u062c \u0627\u0644\u0628\u0627\u062d\u062b \u0645\u0646 \u062f\u0644\u0627\u0644\u0627\u062a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u0627\u0644\u0645\u0647\u0645 \u0645\u062f\u0649 \u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0644\u0623\u062d\u0648\u0627\u0644 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646\u060c \u0648\u0645\u0634\u0627\u0631\u0643\u062a\u064e\u0647 \u0625\u064a\u0627\u0647\u0645 \u0641\u064a \u0645\u0635\u0627\u0628\u0647\u0645\u060c \u0648\u062a\u0637\u064a\u064a\u0628\u064e\u0647 \u0623\u0646\u0641\u0633\u064e \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646\u060c \u0648\u062a\u0642\u062f\u064a\u0631\u064e\u0647 \u062b\u0628\u0627\u062a\u064e \u0627\u0644\u062b\u0627\u0628\u062a\u064a\u0646.","\u0648\u0628\u0627\u0644\u062a\u062a\u0628\u0639 \u0644\u0623\u062d\u0648\u0627\u0644 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0627\u062a\u060c \u0644\u0627 \u0646\u062c\u062f \u0623\u0645 \u062d\u0628\u064a\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0647\u064a \u0627\u0644\u0648\u062d\u064a\u062f\u0629 \u0627\u0644\u062a\u064a \u0627\u0639\u062a\u0646\u0649 \u0627\u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0643\u0631\u064a\u0645 \ufdfa \u0628\u0623\u0645\u0631\u0647\u0627 \u0648\u0648\u0627\u0633\u0627\u0647\u0627 \u0641\u064a \u0645\u0635\u0627\u0628\u0647\u0627\u060c \u0628\u0644 \u0633\u0628\u0642 \u0630\u0644\u0643 \u0635\u0646\u064a\u0639\u064f\u0647 \u0627\u0644\u0645\u0628\u0627\u0631\u0643 \u0645\u0639 \u0633\u0648\u062f\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627\u060c \u0641\u0644\u0645\u0627 \u0631\u062c\u0639\u062a \u0645\u0639 \u0632\u0648\u062c\u0647\u0627 \u0625\u0644\u0649 \u0645\u0643\u0629 \u0645\u0646 \u0627\u0644\u062d\u0628\u0634\u0629 \u062a\u064f\u0648\u0641\u0651\u064a \u0632\u0648\u062c\u064f\u0647\u0627 \u0627\u0644\u0633\u0643\u0631\u0627\u0646 \u0628\u0646 \u0639\u0645\u0631\u0648\u060c \u0641\u0644\u0645\u0627 \u062d\u0644\u064e\u0651\u062a \u0623\u0631\u0633\u0644 \u0625\u0644\u064a\u0647\u0627 \ufdfa \u0648\u062e\u0637\u0628\u0647\u0627\u060c \u0641\u0642\u0627\u0644\u062a: \u0623\u0645\u0631\u064a \u0625\u0644\u064a\u0643 \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0645\u064f\u0631\u064a \u0631\u062c\u0644\u0627\u064b \u0645\u0646 \u0642\u0648\u0645\u0643 \u064a\u064f\u0632\u0648\u0650\u0651\u062c\u0643\xbb\u060c \u0641\u0623\u0645\u0631\u062a \u062d\u0627\u0637\u0628 \u0628\u0646 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0639\u0628\u062f \u0634\u0645\u0633 \u0628\u0646 \u0639\u0628\u062f \u0648\u062f \u0641\u0632\u0648\u0651\u062c\u0647\u0627\u060c \u0641\u0643\u0627\u0646\u062a \u0623\u0648\u0644 \u0627\u0645\u0631\u0623\u0629 \u062a\u0632\u0648\u062c\u0647\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0639\u062f \u062e\u062f\u064a\u062c\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627.","\u0648\u064a\u064f\u0639\u062f\u0651 \u0647\u0630\u0627\u0646 \u0627\u0644\u062d\u062f\u062b\u0627\u0646 \u0645\u0624\u0634\u0631\u064e\u064a\u0646 \u0648\u0627\u0636\u062d\u064e\u064a\u0646 \u0645\u0646 \u0645\u0624\u0634\u0631\u0627\u062a \u062d\u0643\u0645\u0629 \u062a\u0639\u062f\u062f\u0647 \ufdfa \u0641\u064a \u0627\u0644\u0632\u0648\u0627\u062c \u0628\u0634\u0643\u0644 \u0639\u0627\u0645\u060c \u0648\u0644\u0647\u0645\u0627 \u062f\u0644\u0627\u0644\u062a\u0647\u0645\u0627 \u0648\u062d\u0643\u0645\u062a\u0647\u0645\u0627 \u0627\u0644\u0628\u0627\u0644\u063a\u0629 \u0641\u064a \u0627\u0644\u0627\u0647\u062a\u0645\u0627\u0645 \u0628\u0627\u0644\u0646\u0633\u0627\u0621 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u0627\u062a \u0628\u0634\u0643\u0644 \u062e\u0627\u0635\u060c \u0647\u0630\u0627 \u0641\u0636\u0644\u0627\u064b \u0639\u0645\u0627 \u064a\u0645\u0643\u0646 \u0623\u0646 \u064a\u064f\u0642\u0627\u0644 \u0645\u0646 \u0623\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0643\u0627\u0646 \u064a\u0647\u062f\u0641 \u0623\u064a\u0636\u0627\u064b \u0645\u0646 \u0648\u0631\u0627\u0621 \u0627\u0644\u0632\u0648\u0627\u062c \u0628\u0623\u0645 \u062d\u0628\u064a\u0628\u0629 \u0625\u0644\u0649 \u062a\u062e\u0641\u064a\u0641 \u0639\u062f\u0627\u0648\u0629 \u0628\u0646\u064a \u0623\u0645\u064a\u0629 \u0628\u0634\u0643\u0644 \u0639\u0627\u0645\u060c \u0648\u062a\u062e\u0641\u064a\u0641 \u0639\u062f\u0627\u0648\u0629 \u0632\u0639\u064a\u0645\u0647\u0645 \u0623\u0628\u064a \u0633\u0641\u064a\u0627\u0646 -\u0648\u0647\u0648 \u0648\u0627\u0644\u062f\u0647\u0627- \u0628\u0634\u0643\u0644 \u0623\u062e\u0635 \u0644\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0646\u0628\u064a\u0651\u0647 \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0641\u0627\u0644\u062a\u0623\u0644\u064a\u0641 \u0644\u0644\u0625\u0633\u0644\u0627\u0645 \u0623\u0635\u0644 \u0648\u0627\u0631\u062f \u0641\u064a \u0627\u0644\u0633\u064a\u0631\u0629\u060c \u0648\u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0643\u0627\u0646 \u062d\u0631\u064a\u0635\u0627\u064b \u0639\u0644\u0649 \u0647\u062f\u0627\u064a\u0629 \u0642\u0648\u0645\u0647 \u0628\u0643\u0644 \u0648\u0633\u064a\u0644\u0629 \u0645\u0645\u0643\u0646\u0629 \u0644\u0627 \u062a\u062a\u0646\u0627\u0641\u0649 \u0645\u0639 \u0642\u064a\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0645\u0628\u0627\u062f\u0626\u0647."],t.s)
