B.axd=s(["\u0628\u0639\u062f \u0639\u0627\u0645\u064d \u0645\u0646 \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0627\u0644\u062a\u064a \u062c\u0645\u0639\u062a \u0631\u0633\u0648\u0644\u064e \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0627\u0644\u062e\u0632\u0631\u062c \u0639\u0646\u062f \u0639\u0642\u0628\u0629 \u0645\u0650\u0646\u0649 \u0641\u064a \u0645\u0648\u0633\u0645 \u0627\u0644\u062d\u062c\u060c \u0642\u064e\u062f\u0650\u0645\u064e \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0633\u0645 \u0627\u062b\u0646\u0627 \u0639\u0634\u0631 \u0631\u062c\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0641\u0642\u0627\u0628\u0644\u0648\u0647 \ufdfa \u0641\u064a \u0627\u0644\u0645\u0643\u0627\u0646 \u0630\u0627\u062a\u0647\u060c \u0648\u0628\u0627\u064a\u0639\u0648\u0647 \u0628\u064a\u0639\u0629\u064e \u0627\u0644\u0639\u0642\u0628\u0629 \u0627\u0644\u0623\u0648\u0644\u0649\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0639\u0634\u0631\u0629\u064b \u0645\u0646 \u0627\u0644\u062e\u0632\u0631\u062c \u0648\u0627\u062b\u0646\u064a\u0646 \u0645\u0646 \u0627\u0644\u0623\u0648\u0633\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u062f\u0644\u0627\u0644\u0629\u064c \u0648\u0627\u0636\u062d\u0629 \u0639\u0644\u0649 \u0646\u0634\u0627\u0637 \u0648\u0641\u062f \u0627\u0644\u062e\u0632\u0631\u062c \u0627\u0644\u0630\u064a\u0646 \u0623\u0633\u0644\u0645\u0648\u0627 \u0641\u064a \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0645\u0627\u0636\u064a\u061b \u0625\u0630 \u062a\u0631\u0643\u0651\u0632 \u062c\u0647\u062f\u064f\u0647\u0645 \u0639\u0644\u0649 \u0648\u0633\u0637\u0647\u0645 \u0627\u0644\u0642\u0628\u0644\u064a \u0628\u0627\u0644\u062f\u0631\u062c\u0629 \u0627\u0644\u0623\u0648\u0644\u0649\u060c \u063a\u064a\u0631 \u0623\u0646\u0647\u0645 \u062a\u0645\u0643\u0651\u0646\u0648\u0627 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647 \u0645\u0646 \u0627\u062c\u062a\u0630\u0627\u0628 \u0631\u062c\u0627\u0644 \u0627\u0644\u0623\u0648\u0633\u060c \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0628\u062f\u0627\u064a\u0629 \u0627\u0626\u062a\u0644\u0627\u0641 \u0627\u0644\u0642\u0628\u064a\u0644\u062a\u064a\u0646 \u062a\u062d\u062a \u0631\u0627\u064a\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","\u0648\u0642\u062f \u062a\u062d\u062f\u0651\u062b \u0639\u0628\u0627\u062f\u0629\u064f \u0628\u0646 \u0627\u0644\u0635\u0627\u0645\u062a \u0627\u0644\u062e\u0632\u0631\u062c\u064a \u0639\u0646 \u062a\u0644\u0643 \u0627\u0644\u0628\u064a\u0639\u0629 \u0641\u0642\u0627\u0644: \xab\u0643\u0646\u062a \u0641\u064a\u0645\u0646 \u062d\u0636\u0631 \u0627\u0644\u0639\u0642\u0628\u0629 \u0627\u0644\u0623\u0648\u0644\u0649\u060c \u0648\u0643\u0646\u0627 \u0627\u062b\u0646\u064a \u0639\u0634\u0631 \u0631\u062c\u0644\u0627\u064b\u060c \u0641\u0628\u0627\u064a\u0639\u0646\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u0649 \u0628\u064a\u0639\u0629 \u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0630\u0644\u0643 \u0642\u0628\u0644 \u0623\u0646 \u062a\u064f\u0641\u062a\u0631\u0636 \u0639\u0644\u064a\u0646\u0627 \u0627\u0644\u062d\u0631\u0628: \u0639\u0644\u0649 \u0623\u0644\u0627 \u0646\u0634\u0631\u0643 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u0646\u0633\u0631\u0642\u060c \u0648\u0644\u0627 \u0646\u0632\u0646\u064a\u060c \u0648\u0644\u0627 \u0646\u0642\u062a\u0644 \u0623\u0648\u0644\u0627\u062f\u0646\u0627\u060c \u0648\u0644\u0627 \u0646\u0623\u062a\u064a \u0628\u0628\u0647\u062a\u0627\u0646 \u0646\u0641\u062a\u0631\u064a\u0647 \u0628\u064a\u0646 \u0623\u064a\u062f\u064a\u0646\u0627 \u0648\u0623\u0631\u062c\u0644\u0646\u0627\u060c \u0648\u0644\u0627 \u0646\u0639\u0635\u064a\u0647 \u0641\u064a \u0645\u0639\u0631\u0648\u0641\u060c \u0641\u0625\u0646 \u0648\u0641\u064a\u062a\u0645 \u0641\u0644\u0643\u0645 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0625\u0646 \u063a\u064e\u0634\u0650\u064a\u062a\u0645 \u0645\u0646 \u0630\u0644\u0643 \u0634\u064a\u0626\u0627\u064b \u0641\u0623\u0645\u0631\u0643\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644\u060c \u0625\u0646 \u0634\u0627\u0621 \u063a\u0641\u0631 \u0648\u0625\u0646 \u0634\u0627\u0621 \u0639\u0630\u064e\u0651\u0628\xbb.","\u0648\u0628\u0646\u0648\u062f \u0647\u0630\u0647 \u0627\u0644\u0628\u064a\u0639\u0629 \u0647\u064a \u0627\u0644\u062a\u064a \u0628\u0627\u064a\u0639 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0646\u0633\u0627\u0621\u064e \u0641\u064a\u0645\u0627 \u0628\u0639\u062f\u060c \u0648\u0644\u0630\u0644\u0643 \u0639\u064f\u0631\u0641\u062a \u0628\u0627\u0633\u0645 \u0628\u064a\u0639\u0629 \u0627\u0644\u0646\u0633\u0627\u0621."],t.s)
