B.aHO=s(["\u0644\u062c\u0623\u062a \u0642\u0631\u064a\u0634\u064c \u0625\u0644\u0649 \u0627\u0644\u062d\u0628\u0633 \u0623\u0633\u0644\u0648\u0628\u0627\u064b \u0644\u0642\u0637\u0639 \u0637\u0631\u064a\u0642 \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0641\u0643\u0644 \u0645\u0646 \u062a\u064f\u0642\u0628\u064e\u0636 \u0639\u0644\u064a\u0647 \u0648\u0647\u0648 \u064a\u0631\u0648\u0645\u0647\u0627 \u0643\u0627\u0646\u062a \u062a\u0632\u062c\u064f\u0651 \u0628\u0647 \u062f\u0627\u062e\u0644 \u0623\u062d\u062f \u0627\u0644\u0628\u064a\u0648\u062a\u060c \u062a\u0634\u064f\u062f\u064f\u0651 \u064a\u062f\u064a\u0647 \u0648\u0631\u062c\u0644\u064a\u0647 \u0628\u0627\u0644\u0642\u064a\u0648\u062f\u060c \u0648\u062a\u064f\u0633\u0644\u0650\u0651\u0637 \u0639\u0644\u064a\u0647 \u0627\u0644\u062d\u0631\u0627\u0633\u0629 \u0648\u0627\u0644\u0631\u0642\u0627\u0628\u0629 \u0627\u0644\u0645\u0634\u062f\u062f\u0629 \u062d\u062a\u0649 \u0644\u0627 \u064a\u0646\u0641\u0644\u062a\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u062d\u0628\u0633 \u0623\u062d\u064a\u0627\u0646\u0627\u064b \u0641\u064a \u0628\u064a\u062a \u0644\u0627 \u0633\u0642\u0641 \u0644\u0647\u060c \u0643\u0645\u0627 \u0641\u0639\u0644\u062a \u0628\u0639\u064a\u0627\u0634 \u0648\u0647\u0634\u0627\u0645 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627\u060c \u0641\u064a\u0636\u0627\u0641 \u0625\u0644\u0649 \u0648\u062d\u0634\u0629 \u0627\u0644\u0633\u062c\u0646 \u0644\u0638\u0649 \u0627\u0644\u0634\u0645\u0633 \u0641\u064a \u0628\u064a\u0626\u0629 \u0645\u0643\u0629 \u0627\u0644\u062c\u0628\u0644\u064a\u0629 \u0627\u0644\u0634\u062f\u064a\u062f\u0629 \u0627\u0644\u062d\u0631\u0627\u0631\u0629.","\u0648\u0643\u0627\u0646\u062a \u0642\u064a\u0627\u062f\u0629 \u0642\u0631\u064a\u0634 \u062a\u0628\u062a\u063a\u064a \u0645\u0646 \u0648\u0631\u0627\u0621 \u0630\u0644\u0643 \u0645\u0646\u0639 \u0627\u0644\u0645\u062d\u0628\u0648\u0633\u064a\u0646 \u0645\u0646 \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0648\u062c\u0639\u0644 \u0645\u0635\u064a\u0631\u0647\u0645 \u0639\u0628\u0631\u0629\u064b \u0644\u0643\u0644 \u0645\u0646 \u064a\u064f\u0641\u0643\u0650\u0651\u0631 \u0641\u064a \u0627\u0644\u0633\u064a\u0631 \u0639\u0644\u0649 \u062f\u0631\u0628\u0647\u0645\u060c \u063a\u064a\u0631 \u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0644\u0648\u0628 \u0644\u0645 \u064a\u064f\u0648\u0642\u0641 \u062a\u062f\u0641\u0642 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a\u064f\u0651 \ufdfa \u0628\u0639\u062f \u0647\u062c\u0631\u062a\u0647 \u064a\u0642\u0646\u062a \u0648\u064a\u062f\u0639\u0648 \u0644\u0644\u0645\u0633\u062a\u0636\u0639\u0641\u064a\u0646 \u0641\u064a \u0645\u0643\u0629\u060c \u064a\u0630\u0643\u0631 \u0639\u0627\u0645\u062a\u0647\u0645 \u062a\u0627\u0631\u0629\u064b \u0648\u0628\u0639\u0636\u0647\u0645 \u0628\u0623\u0633\u0645\u0627\u0626\u0647\u0645 \u062a\u0627\u0631\u0629\u064b \u0623\u062e\u0631\u0649\u060c \u0641\u0639\u0646 \u0623\u0628\u064a \u0647\u0631\u064a\u0631\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0643\u0627\u0646 \u0625\u0630\u0627 \u0631\u0641\u0639 \u0631\u0623\u0633\u0647 \u0645\u0646 \u0627\u0644\u0631\u0643\u0639\u0629 \u0627\u0644\u0623\u062e\u064a\u0631\u0629 \u0642\u0627\u0644: \xab\u0627\u0644\u0644\u0647\u0645 \u0623\u0646\u062c\u0650 \u0639\u064a\u0627\u0634\u064e \u0628\u0646 \u0623\u0628\u064a \u0631\u0628\u064a\u0639\u0629\u060c \u0627\u0644\u0644\u0647\u0645 \u0623\u0646\u062c\u0650 \u0633\u0644\u0645\u0629\u064e \u0628\u0646 \u0647\u0634\u0627\u0645\u060c \u0627\u0644\u0644\u0647\u0645 \u0623\u0646\u062c\u0650 \u0627\u0644\u0648\u0644\u064a\u062f\u064e \u0628\u0646 \u0627\u0644\u0648\u0644\u064a\u062f\u060c \u0627\u0644\u0644\u0647\u0645 \u0623\u0646\u062c\u0650 \u0627\u0644\u0645\u0633\u062a\u0636\u0639\u0641\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0627\u0644\u0644\u0647\u0645 \u0627\u0634\u062f\u064f\u062f \u0648\u0637\u0623\u062a\u064e\u0643 \u0639\u0644\u0649 \u0645\u064f\u0636\u064e\u0631\u060c \u0627\u0644\u0644\u0647\u0645 \u0627\u062c\u0639\u0644\u0647\u0627 \u0633\u0646\u064a\u0646 \u0643\u0633\u0650\u0646\u0650\u064a \u064a\u0648\u0633\u0641\xbb.","\u0648\u0644\u0645 \u064a\u062a\u0631\u0643 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0623\u0645\u0631 \u0639\u064a\u0627\u0634 \u0648\u0635\u0627\u062d\u0628\u0647 \u062f\u0648\u0646 \u0633\u0639\u064a\u060c \u0641\u0642\u062f \u0646\u062f\u064e\u0628 \u0627\u0644\u0646\u0628\u064a\u064f\u0651 \ufdfa \u0631\u062c\u0644\u0627\u064b \u0644\u0647\u0630\u0647 \u0627\u0644\u0645\u0647\u0645\u0629\u060c \u0641\u0627\u0633\u062a\u0639\u062f\u064e\u0651 \u0644\u0647\u0627 \u0648\u0627\u0633\u062a\u0643\u0645\u0644 \u0639\u062f\u064e\u0651\u062a\u0647\u0627\u060c \u0648\u062f\u062e\u0644 \u0645\u0643\u0629\u060c \u0648\u0628\u0644\u063a \u0628\u0630\u0643\u0627\u0626\u0647 \u0648\u0627\u0642\u062a\u062f\u0627\u0631\u0647 \u0627\u0644\u0628\u064a\u062a\u064e \u0627\u0644\u0630\u064a \u062d\u064f\u0628\u0633\u0627 \u0641\u064a\u0647\u060c \u0641\u0623\u0637\u0644\u0642 \u0633\u0631\u0627\u062d\u0647\u0645\u0627 \u0648\u0639\u0627\u062f \u0628\u0647\u0645\u0627 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629."],t.s)
