B.aKU=s(["\u0643\u0627\u0646 \u0645\u0646 \u0646\u062a\u0627\u0626\u062c \u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0645\u0628\u0627\u064a\u0639\u062a\u0647\u0645 \u0648\u062a\u0639\u0647\u062f\u0647\u0645 \u0628\u0627\u0644\u0646\u0635\u0631\u0629 \u0623\u0646 \u062f\u0639\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0641\u0638\u0647\u0631\u062a \u0639\u0644\u0649 \u0625\u062b\u0631 \u0630\u0644\u0643 \u0638\u0627\u0647\u0631\u0629\u064c \u0639\u0638\u064a\u0645\u0629 \u0645\u0646 \u0627\u0644\u062a\u0643\u0627\u0641\u0644 \u0644\u0645 \u062a\u0639\u0631\u0641 \u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0644\u0647\u0627 \u0646\u0638\u064a\u0631\u0627\u064b\u061b \u0625\u0630 \u0641\u062a\u062d\u062a \u0628\u064a\u0648\u062a \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0623\u0628\u0648\u0627\u0628\u0647\u0627 \u0648\u0642\u0644\u0648\u0628 \u0623\u0635\u062d\u0627\u0628\u0647\u0627 \u0644\u0648\u0641\u0648\u062f \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646\u060c \u0641\u0623\u0635\u0628\u062d \u0627\u0644\u0645\u0633\u0643\u0646 \u0627\u0644\u0648\u0627\u062d\u062f \u064a\u0636\u0645\u0651 \u0627\u0644\u0645\u0647\u0627\u062c\u0631 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a\u060c \u0648\u0627\u0644\u0645\u0647\u0627\u062c\u0650\u0631\u0629 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a\u0629\u060c \u064a\u062a\u0642\u0627\u0633\u0645\u0648\u0646 \u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u0645\u0643\u0627\u0646 \u0648\u0627\u0644\u0637\u0639\u0627\u0645 \u0648\u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a\u0629.","\u0648\u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0628\u064a\u0648\u062a\u0627\u062a \u0627\u0644\u062d\u0627\u0636\u0646\u0629: \u062f\u0627\u0631\u064f \u0645\u064f\u0628\u064e\u0634\u0650\u0651\u0631 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0646\u0630\u0631 \u0628\u0646 \u0632\u064e\u0646\u0628\u0631 \u0628\u0642\u064f\u0628\u0627\u0621 \u0627\u0644\u062a\u064a \u0646\u0632\u0644 \u0628\u0647\u0627 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0648\u0645\u0646 \u0644\u062d\u0642 \u0628\u0647 \u0645\u0646 \u0623\u0647\u0644\u0647 \u0648\u0642\u0648\u0645\u0647 \u0648\u0627\u0628\u0646\u062a\u064f\u0647 \u062d\u0641\u0635\u0629 \u0648\u0632\u0648\u062c\u0647\u0627 \u0648\u0639\u064a\u0651\u0627\u0634 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629.","\u0648\u062f\u0627\u0631\u064f \u062e\u064f\u0628\u064e\u064a\u0628 \u0628\u0646 \u0625\u0633\u0627\u0641 \u0623\u062e\u064a \u0628\u0646\u064a \u0627\u0644\u062d\u0627\u0631\u062b \u0628\u0646 \u0627\u0644\u062e\u0632\u0631\u062c \u0628\u0627\u0644\u0633\u0646\u062d \u0627\u0644\u062a\u064a \u0646\u0632\u0644 \u0628\u0647\u0627 \u0637\u0644\u062d\u0629 \u0628\u0646 \u0639\u0628\u064a\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u062b\u0645\u0627\u0646 \u0648\u0623\u0645\u0647 \u0648\u0635\u0647\u064a\u0628 \u0628\u0646 \u0633\u0646\u0627\u0646\u060c \u0648\u062f\u0627\u0631\u064f \u0623\u0633\u0639\u062f \u0628\u0646 \u0632\u064f\u0631\u0627\u0631\u0629 \u0645\u0646 \u0628\u0646\u064a \u0627\u0644\u0646\u062c\u0627\u0631 \u0648\u064a\u064f\u0642\u0627\u0644 \u0625\u0646 \u062d\u0645\u0632\u0629 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0646\u0632\u0644 \u0628\u0647\u0627\u060c \u0648\u062f\u0627\u0631\u064f \u0633\u0639\u062f \u0628\u0646 \u062e\u064e\u064a\u062b\u0645\u0629 \u0623\u062e\u064a \u0628\u0646\u064a \u0627\u0644\u0646\u062c\u0627\u0631 \u0648\u0643\u0627\u0646\u062a \u062a\u064f\u0639\u0631\u064e\u0641 \u0628\u0628\u064a\u062a \u0627\u0644\u0639\u064f\u0632\u0651\u0627\u0628 \u0625\u0630 \u0646\u0632\u0644 \u0628\u0647\u0627 \u0627\u0644\u0623\u0639\u0632\u0627\u0628 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646.","\u0648\u062f\u0627\u0631\u064f \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0633\u064e\u0644\u0650\u0645\u0629 \u0623\u062e\u064a \u0628\u064e\u0644\u0639\u064e\u062c\u0644\u0627\u0646 \u0628\u0642\u0628\u0627\u0621 \u0627\u0644\u062a\u064a \u0636\u0645\u0651\u062a \u0639\u064f\u0628\u064a\u062f\u0629 \u0628\u0646 \u0627\u0644\u062d\u0627\u0631\u062b \u0648\u0623\u0645\u0647 \u0633\u064f\u062e\u064e\u064a\u0644\u0629 \u0648\u0645\u0650\u0633\u0637\u062d \u0628\u0646 \u0623\u062b\u0627\u062b\u0629 \u0628\u0646 \u0639\u0628\u0651\u0627\u062f \u0628\u0646 \u0627\u0644\u0645\u0637\u0644\u0628 \u0648\u0627\u0644\u0637\u0641\u064a\u0644 \u0628\u0646 \u0627\u0644\u062d\u0627\u0631\u062b \u0648\u0637\u064f\u0644\u064e\u064a\u0628 \u0628\u0646 \u0639\u064f\u0645\u064a\u0631 \u0648\u0627\u0644\u062d\u0635\u064a\u0646 \u0628\u0646 \u0627\u0644\u062d\u0627\u0631\u062b\u060c \u0648\u062f\u0627\u0631\u064f \u0628\u0646\u064a \u062c\u064e\u062d\u062c\u064e\u0628\u0649 \u0648\u0627\u062d\u062a\u0636\u0646\u0647\u0645 \u0645\u0646\u0630\u0631 \u0628\u0646 \u0645\u062d\u0645\u062f \u0628\u0646 \u0639\u0642\u0628\u0629 \u0648\u0646\u0632\u0644 \u0639\u0646\u062f\u0647 \u0627\u0644\u0632\u0628\u064a\u0631 \u0628\u0646 \u0627\u0644\u0639\u0648\u0627\u0645 \u0648\u0632\u0648\u062c\u0647 \u0623\u0633\u0645\u0627\u0621 \u0628\u0646\u062a \u0623\u0628\u064a \u0628\u0643\u0631 \u0648\u0623\u0628\u0648 \u0633\u064e\u0628\u0631\u0629 \u0628\u0646 \u0623\u0628\u064a \u0648\u0647\u0628 \u0648\u0632\u0648\u062c\u062a\u0647 \u0623\u0645 \u0643\u0644\u062b\u0648\u0645 \u0628\u0646\u062a \u0633\u0647\u064a\u0644.","\u0648\u062f\u0627\u0631\u064f \u0628\u0646\u064a \u0639\u0628\u062f \u0627\u0644\u0623\u0634\u0647\u0644 \u0648\u0627\u062d\u062a\u0636\u0646\u0647\u0645 \u0633\u0639\u062f \u0628\u0646 \u0645\u0639\u0627\u0630 \u0628\u0646 \u0627\u0644\u0646\u0639\u0645\u0627\u0646 \u0641\u0646\u0632\u0644 \u0628\u0647\u0627 \u0645\u0635\u0639\u0628 \u0628\u0646 \u0639\u0645\u064a\u0631 \u0648\u0632\u0648\u062c\u062a\u0647 \u062d\u064e\u0645\u0646\u0629 \u0628\u0646\u062a \u062c\u062d\u0634\u060c \u0648\u062f\u0627\u0631\u064f \u0628\u0646\u064a \u0627\u0644\u0646\u062c\u0627\u0631 \u0648\u0627\u062d\u062a\u0636\u0646\u0647\u0645 \u0623\u0648\u0633 \u0628\u0646 \u062b\u0627\u0628\u062a \u0628\u0646 \u0627\u0644\u0645\u0646\u0630\u0631 \u0641\u0646\u0632\u0644 \u0628\u0647\u0627 \u0639\u062b\u0645\u0627\u0646 \u0628\u0646 \u0639\u0641\u0627\u0646 \u0648\u0632\u0648\u062c\u062a\u0647 \u0631\u064f\u0642\u064a\u0651\u0629 \u0628\u0646\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa.","\u0648\u062a\u0645\u0651\u062a \u0627\u0644\u0645\u0624\u0627\u062e\u0627\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u0648\u0643\u0627\u0646\u062a \u0647\u0630\u0647 \u0627\u0644\u0645\u0642\u0627\u0633\u0645\u0629 \u0645\u0646 \u0623\u0639\u0638\u0645 \u0627\u0644\u0639\u0648\u0627\u0645\u0644 \u0627\u0644\u062a\u064a \u0645\u0647\u0651\u062f\u062a \u0644\u0625\u0642\u0627\u0645\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0635\u062d\u0627\u0628\u062a\u0647 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0645\u0639\u0647 \u0641\u064a \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0625\u0642\u0627\u0645\u0629\u064b \u0637\u064a\u0628\u0629\u064b \u062a\u0646\u0628\u0636 \u0628\u0648\u062f\u0651 \u0627\u0644\u0623\u062e\u0648\u0629 \u0627\u0644\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u0629."],t.s)
