B.aUL=s(["\u0648\u0644\u0639\u0644\u064e\u0651 \u0642\u0627\u0626\u0644\u0627\u064b \u064a\u062a\u0633\u0627\u0621\u0644: \u0644\u0645\u0627\u0630\u0627 \u0644\u0645 \u062a\u064f\u0633\u062c\u0650\u0651\u0644 \u0627\u0644\u0645\u0635\u0627\u062f\u0631 \u062e\u0644\u0627\u0641\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0648\u0642\u0639 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0628\u064a\u0648\u062a\u060c \u0648\u0623\u064a\u0646 \u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0645\u0627 \u0627\u0634\u062a\u064f\u0647\u0631\u0646 \u0628\u0647 \u0645\u0646 \u0645\u064f\u0634\u0627\u0643\u0633\u0627\u062a\u061f","\u0648\u0627\u0644\u062c\u0648\u0627\u0628 \u0623\u0646\u0647 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u062d\u0642\u060c \u0627\u0644\u0630\u064a \u062c\u0639\u0644 \u062a\u0642\u0648\u0649 \u0627\u0644\u0644\u0647 \u0623\u0633\u0627\u0633\u0627\u064b \u0644\u062a\u0635\u0631\u064f\u0651\u0641 \u0643\u0644 \u0646\u0641\u0633\u060c \u0648\u063a\u0631\u0633 \u0627\u0644\u0623\u062e\u0644\u0627\u0642 \u0627\u0644\u0633\u0627\u0645\u064a\u0629 \u0627\u0644\u062a\u064a \u0641\u0631\u0636\u062a \u0627\u0644\u0623\u062e\u0648\u064e\u0651\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0646\u064f\u0635\u0631\u0629 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0641\u0643\u0644\u064f\u0651 \u0645\u0646 \u0623\u0633\u0644\u0645 \u0648\u0628\u0627\u064a\u064e\u0639 \u0648\u0643\u0644\u064f\u0651 \u0645\u0646 \u0623\u0633\u0644\u0645\u062a \u0648\u0628\u0627\u064a\u064e\u0639\u062a \u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0645\u0627 \u064a\u064f\u0624\u0645\u064e\u0631\u0648\u0646 \u0628\u0647 \u0648\u064a\u064f\u062e\u0644\u0635\u0648\u0646 \u0641\u064a\u0645\u0627 \u064a\u0642\u0648\u0644\u0648\u0646\u060c \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0633\u0631 \u0648\u0627\u0644\u0639\u0644\u0646 \u0648\u064a\u0631\u0647\u0628\u0648\u0646 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631 \u0648\u064a\u0631\u063a\u0628\u0648\u0646 \u0641\u064a \u0627\u0644\u062b\u0648\u0627\u0628 \u0648\u064a\u0637\u0645\u0639\u0648\u0646 \u0641\u064a \u0627\u0644\u062c\u0646\u0629\u060c \u0641\u0622\u0645\u0646\u062a \u0627\u0644\u0646\u0641\u0648\u0633 \u0648\u0627\u0637\u0645\u0623\u0646\u062a\u060c \u0648\u0627\u062d\u062a\u0636\u0646\u062a \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a\u0629\u064f \u0627\u0644\u0645\u0647\u0627\u062c\u0650\u0631\u0629 \u0643\u0623\u0646\u0647\u0627 \u0623\u062e\u062a\u0647\u0627 \u0645\u0646 \u0623\u0645\u0647\u0627 \u0648\u0623\u0628\u064a\u0647\u0627\u060c \u0648\u0627\u0644\u0643\u0644\u064f\u0651 \u064a\u0639\u0645\u0644 \u0645\u0646 \u0623\u062c\u0644 \u0645\u0635\u0644\u062d\u0629 \u0627\u0644\u0643\u0644\u060c \u062d\u062a\u0649 \u0625\u0646 \u0627\u0644\u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645 \u0644\u064a\u062e\u0627\u0641 \u0623\u0646 \u064a\u0630\u0647\u0628 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a\u064f\u0651 \u0628\u0627\u0644\u0623\u062c\u0631 \u0643\u0644\u0647\u060c \u0641\u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u062a\u0643\u0627\u0641\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a \u0641\u064a \u0623\u062c\u0644\u0649 \u0635\u0648\u0631\u0629\u064d \u0648\u0623\u0642\u062f\u0633 \u0648\u0627\u0642\u0639\u0629."],t.s)
