B.aUV=s(["\u0644\u0645 \u064a\u064e\u0639\u0644\u064e\u0645 \u0628\u062e\u0631\u0648\u062c \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0644\u0647\u062c\u0631\u0629 \u0623\u062d\u062f\u064c \u0625\u0644\u0627 \u0639\u0644\u064a\u064f\u0651 \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628\u060c \u0648\u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0627\u0644\u0635\u062f\u064a\u0642\u060c \u0648\u0622\u0644 \u0623\u0628\u064a \u0628\u0643\u0631\u060c \u0623\u0645\u0627 \u0639\u0644\u064a\u064c\u0651 \u0641\u0625\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0645\u064e\u0631\u0647 \u0623\u0646 \u064a\u0628\u0642\u0649 \u0628\u0645\u0643\u0629\u064e \u062d\u062a\u0649 \u064a\u0624\u062f\u0650\u0651\u064a\u064e \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0648\u062f\u0627\u0626\u0639\u064e \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0639\u0646\u062f\u064e\u0647 \u0644\u0644\u0646\u0627\u0633\u060c \u0648\u0643\u0627\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0644\u064a\u0633 \u0628\u0645\u0643\u0629\u064e \u0623\u062d\u062f\u064c \u0639\u0646\u062f\u064e\u0647 \u0634\u064a\u0621\u064c \u064a\u064e\u062e\u0634\u0649 \u0639\u0644\u064a\u0647\u060c \u0625\u0644\u0627 \u0648\u0636\u064e\u0639\u064e\u0647 \u0639\u0646\u062f\u064e\u0647\u060c \u0644\u0645\u0627 \u064a\u0639\u0644\u0645\u064f \u0645\u0646 \u0635\u0650\u062f\u0642\u0650\u0647 \u0648\u0623\u0645\u0627\u0646\u062a\u0650\u0647.","\u0648\u0643\u0627\u0646 \u0627\u0644\u0645\u064a\u0639\u0627\u062f\u064f \u0628\u064a\u0646 \u0627\u0644\u0631\u0633\u0648\u0644\u0650 \ufdfa \u0648\u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0641\u062e\u0631\u062c\u0627 \u0645\u0646 \u062e\u064e\u0648\u062e\u0629\u064d \u0644\u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0641\u064a \u0638\u0647\u0631\u0650 \u0628\u064a\u062a\u0650\u0647\u060c \u0648\u0647\u064a \u0628\u0627\u0628 \u0635\u063a\u064a\u0631 \u062e\u0644\u0641\u064a \u0641\u064a \u0627\u0644\u0628\u064a\u062a\u060c \u0648\u0630\u0644\u0643 \u0644\u0644\u0625\u0645\u0639\u0627\u0646\u0650 \u0641\u064a \u0627\u0644\u0627\u0633\u062a\u062e\u0641\u0627\u0621\u0650 \u062d\u062a\u0649 \u0644\u0627 \u062a\u062a\u0628\u0639\u064e\u0647\u0645\u0627 \u0642\u0631\u064a\u0634\u060c \u0648\u062a\u0645\u0646\u0639\u064e\u0647\u0645\u0627 \u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0631\u062d\u0644\u0629\u0650 \u0627\u0644\u0645\u0628\u0627\u0631\u0643\u0629\u060c \u0648\u0642\u062f \u0627\u062a\u064e\u0651\u0639\u062f\u0627 \u0645\u0639 \u0627\u0644\u0644\u064a\u0644\u0650 \u0639\u0644\u0649 \u0623\u0646 \u064a\u0644\u0642\u0627\u0647\u0645\u0627 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u064f\u0631\u064a\u0642\u0650\u0637 \u0641\u064a \u063a\u0627\u0631\u0650 \u062b\u064e\u0648\u0631\u064d \u0628\u0639\u062f \u062b\u0644\u0627\u062b\u0650 \u0644\u064a\u0627\u0644\u064d.","\u064a\u0642\u0641 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u0649 \u0634\u0650\u0639\u0627\u0628 \u0645\u0643\u0629 \u0646\u0627\u0638\u0631\u064b\u0627 \u0625\u0644\u064a\u0647\u0627 \u0646\u0638\u0631\u0629\u064e \u0641\u0631\u0627\u0642\u064d\u060c \u0648\u0642\u0644\u0628\u064f\u0647 \u064a\u0639\u062a\u0635\u0631\u064f\u0647 \u0627\u0644\u0623\u0644\u0645\u060c \u0648\u0644\u0627 \u064a\u0639\u0631\u0641\u064f \u0630\u0644\u0643 \u0627\u0644\u0634\u0639\u0648\u0631\u064e \u0625\u0644\u0627 \u0645\u0646 \u062e\u0631\u062c \u0645\u0646 \u0648\u0637\u0646\u0647 \u0631\u064f\u063a\u0645\u064b\u0627 \u0639\u0646\u0647\u060c \u062a\u0627\u0631\u0643\u064b\u0627 \u0623\u0647\u0644\u0647 \u0648\u0639\u0645\u0644\u0647 \u0648\u0644\u0642\u0627\u0621 \u0627\u0644\u0623\u062d\u0628\u0629\u060c \u0648\u0644\u0643\u0646\u064e\u0651 \u0627\u0644\u062f\u0639\u0648\u0629 \u0644\u0644\u0647 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0627\u0644\u0623\u0648\u0637\u0627\u0646 \u0648\u0623\u063a\u0644\u0649 \u0645\u0646 \u0627\u0644\u0630\u0643\u0631\u064a\u0627\u062a\u060c \u0648\u0642\u062f \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0648\u0627\u0644\u0644\u0647 \u0625\u0646\u0643 \u0644\u062e\u064a\u0631 \u0623\u0631\u0636 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u062d\u0628 \u0623\u0631\u0636 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0648\u0644\u0627 \u0623\u0646\u064a \u0623\u064f\u062e\u0631\u062c\u062a \u0645\u0646\u0643 \u0645\u0627 \u062e\u0631\u062c\u062a\xbb."],t.s)
